!--------------------------------------
MODULE exx_base
  !--------------------------------------
  !! Basic variables and subroutines for calculation of exact exchange (EXX).
  !
  USE kinds,                ONLY : DP
  USE coulomb_vcut_module,  ONLY : vcut_init, vcut_type, vcut_info, &
                                   vcut_get,  vcut_spheric_get
  USE noncollin_module,     ONLY : noncolin
  USE io_global,            ONLY : ionode
  !
  USE control_flags,        ONLY : gamma_only
  USE fft_types,            ONLY : fft_type_descriptor
  USE stick_base,           ONLY : sticks_map, sticks_map_deallocate
  !
  USE io_global,            ONLY : stdout
  !
  IMPLICIT NONE
  !
  SAVE
  !
  ! ... general purpose vars
  !
  COMPLEX(8) :: d_spin(2,2,48)
  !! spin matrices for non collinear calculations
  !
  REAL(8), ALLOCATABLE :: locbuff(:,:,:)
  !! temporary (real) buffer for wfc storage
  REAL(8), ALLOCATABLE :: locmat(:,:,:)
  !! buffer for matrix of localization integrals
  REAL(8), ALLOCATABLE :: exxmat(:,:,:,:)
  !! buffer for matrix of localization integrals (K)
  COMPLEX(8), ALLOCATABLE :: evc0(:,:,:)
  !! old wfc (G-space) needed to compute fock3
  !
  ! ... variables defining the auxiliary k-point grid
  !     used in X BZ integration
  !
  INTEGER :: nq1=1, nq2=1, nq3=1
  !! integers defining the X integration mesh
  INTEGER :: nqs=1
  !! number of points in the q-grid
  INTEGER :: nkqs
  !! total number of different k+q
  REAL(8), ALLOCATABLE :: xkq_collect(:,:)
  !! xkq(3,nkqs) the auxiliary k+q set
  !
  ! ... let xk(:,ik) + xq(:,iq) = xkq(:,ikq) = S(isym)*xk(ik') + G
  !
  !     index_xkq(ik,iq) = ikq
  !     index_xk(ikq)    = ik'
  !     index_sym(ikq)   = isym
  !
  INTEGER, ALLOCATABLE :: index_xkq(:,:)
  !! index_xkq(nks,nqs)
  INTEGER, ALLOCATABLE :: index_xk(:)
  !! index_xk(nkqs)
  INTEGER, ALLOCATABLE :: index_sym(:)
  !! index_sym(nkqs)
  INTEGER, ALLOCATABLE :: rir(:,:)
  !! rotations to take k to q
  INTEGER, ALLOCATABLE :: working_pool(:)
  !! idx of pool that has the k+q-point before rotation
  !
  ! ... Internal:
  LOGICAL :: exx_grid_initialized = .FALSE.
  !
  REAL(8):: exxalfa=0._8
  !! the parameter multiplying the exact-exchange part
  !
  ! ... variables to deal with Coulomb divergence
  !     and related issues
  REAL(8) :: eps  = 1.d-6
  REAL(8) :: eps_qdiv = 1.d-8 ! |q| > eps_qdiv
  REAL(8) :: exxdiv = 0._8
  CHARACTER(32) :: exxdiv_treatment  = ' '
  !
  ! ... x_gamma_extrapolation
  LOGICAL :: x_gamma_extrapolation =.TRUE.
  LOGICAl :: on_double_grid =.FALSE.
  REAL(8) :: grid_factor = 1.d0 !8.d0/7.d0
  !
  LOGICAL :: use_regularization = .TRUE.
  !! Gygi-Baldereschi
  !
  REAL(8) :: yukawa = 0._8
  !! Yukawa method
  !
  REAL(8) :: erfc_scrlen = 0._8
  !! erfc screening
  !
  REAL(8) :: erf_scrlen = 0._8
  !! erf screening
  !
  REAL(8) :: gau_scrlen = 0.d0
  !! gau-pbe screening
  !
  ! ... cutoff techniques
  LOGICAL :: use_coulomb_vcut_ws = .FALSE.
  LOGICAL :: use_coulomb_vcut_spheric = .FALSE.
  REAL(8) :: ecutvcut
  TYPE(vcut_type) :: vcut
  !
  ! ... band parallelism types
  enum, bind(c)
    enumerator :: EXX_BGRP_TYP   = 0 ! unset value
    enumerator :: EXX_BGRP_BANDS = 1 ! distribute bands over band groups
    enumerator :: EXX_BGRP_PAIRS = 2 ! distribute band pairs over band groups 
                                     ! (see Barnes et al., Comput. Phys. Comm., Volume 214, 2017, Pages 52-58)
  end enum
  !! allowed values for exx_bgrp_type
  integer(kind(EXX_BGRP_TYP)) :: exx_bgrp_type ! (initialized in read_namelist)
  !
  TYPE(fft_type_descriptor) :: dfftt 
  !
  COMPLEX(8), ALLOCATABLE :: exxbuff(:,:,:)
  COMPLEX(8), ALLOCATABLE :: exxbuff_d(:,:,:)
  !! Buffers: temporary (complex) buffer for wfc storage



  !





  !
  INTEGER :: npwt
  !! number of plane waves in custom grid (Gamma-only)
  !
  REAL(8), ALLOCATABLE :: x_occupation(:,:)
  !! the weights of auxiliary functions in the density matrix
  !! GPU duplicated data
  REAL(8), ALLOCATABLE :: x_occupation_d(:,:)



  INTEGER :: x_nbnd_occ
  !! number of bands of auxiliary functions with at least 
  !! some x_occupation > eps_occ
  REAL(8), PARAMETER :: eps_occ = 1.d-8
  !! occupation threshold
  !
  REAL(kind=8), DIMENSION(:,:),POINTER :: gt => null()
  !! G-vectors in custom grid
  REAL(kind=8), DIMENSION(:), POINTER :: ggt => null()
  !! G-vectors in custom gri
  REAL(8) :: gcutmt, gkcut
  INTEGER :: gstart_t
  !! gstart_t=2 if ggt(1)=0, =1 otherwise
  INTEGER :: ngmt_g
  !! Total number of G-vectors in custom grid
  !
  INTEGER :: nbndproj
  REAL(8)::  local_thr 
  !! threshold for Lin Lin's SCDM localized orbitals: discard 
  !! contribution to V_x if overlap between localized orbitals
  !! is smaller than "local_thr".
  !! 
  INTEGER :: ibnd_start = 0
  !! starting band index used in bgrp parallelization
  INTEGER :: ibnd_end = 0
  !! ending band index used in bgrp parallelization
  INTEGER :: ibnd_buff_start
  !! starting buffer index used in bgrp parallelization
  INTEGER :: ibnd_buff_end
  !! ending buffer index used in bgrp parallelization
  !
 CONTAINS
  !
  !------------------------------------------------------------------------
  SUBROUTINE exx_mp_init()
    !------------------------------------------------------------------------
    !! 1) Setup the orthopool communicators, which include the (n-1)-th CPU of
    !!    each pool (i.e. orthopool 0, contains CPU 0 of each pool).
    !
    !! 2) Setup global variable \(\text{working_pool}\) which contains the index of the
    !!    pool which has the local copy prior to rotation of the \(\text{ikq}\)-th
    !!    pool.  
    !
    !! 3) \(\text{working_pool(ikq)}\) is also index of the CPU in each orthopool
    !!    which has to broadcast the wavefunction at k-point \(\text{ikq}\).
    !
    USE mp_images,      ONLY : intra_image_comm
    USE mp_pools,       ONLY : my_pool_id
    USE mp_orthopools,  ONLY : mp_start_orthopools, intra_orthopool_comm
    USE mp,             ONLY : mp_sum
    USE klist,          ONLY : nkstot
    !
    IMPLICIT NONE
    !
    INTEGER :: ikq, current_ik, ik
    INTEGER, EXTERNAL :: local_kpoint_index
    !
    IF (nkqs <= 0) CALL errore( "exx_mp_init", "exx_grid_init must be called first!", 1 )
    !
    ! ... mp_start_orthopools contains a check to avoid double initialisation
    CALL mp_start_orthopools( intra_image_comm )
    !
    IF (ALLOCATED(working_pool)) DEALLOCATE( working_pool )
    ALLOCATE( working_pool(nkqs) )
    !
    DO ikq = 1, nkqs
      DO current_ik = 1, nkstot
        ! find the index of point k+q from the global list
        IF (index_xk(ikq) == current_ik) EXIT
      ENDDO
      IF (current_ik>nkstot) CALL errore( "exx_mp_init", "could not find the local index", ikq )
      ! Find the pool-index of the global point, returns -1 if the point
      ! was not in my pool
      ik = local_kpoint_index(nkstot, current_ik)
      !
      ! Set a temporary variable to the index of the pool who did the work
      IF( ik > 0 ) THEN
        working_pool(ikq) = my_pool_id
      ELSE
        working_pool(ikq) = 0
      ENDIF
      !
    ENDDO    
      !
      ! Collect the variable among all the nth CPUs of each pool,
      ! i.e. inside each orto-pool group
    CALL mp_sum( working_pool, intra_orthopool_comm )
    !
  END SUBROUTINE exx_mp_init
  !
  !------------------------------------------------------------------------
  SUBROUTINE exx_grid_init( reinit )
    !------------------------------------------------------------------------
    !!
    !
    USE symm_base,         ONLY : nsym, s
    USE cell_base,         ONLY : bg, at, tpiba
    USE noncollin_module,  ONLY : nspin_lsda, domag
    USE klist,             ONLY : xk, wk, nkstot, nks, qnorm
    USE wvfct,             ONLY : nbnd
    USE start_k,           ONLY : nk1,nk2,nk3
    USE control_flags,     ONLY : iverbosity
    USE mp_pools,          ONLY : inter_pool_comm
    !
    IMPLICIT NONE
    !
    LOGICAL, OPTIONAL :: reinit
    !! reinitialize exx if .TRUE.
    !
    ! ... local variables
    !
    CHARACTER(13) :: sub_name='exx_grid_init'
    INTEGER :: iq1, iq2, iq3, isym, ik, ikq, iq, max_nk, temp_nkqs, idx, sign_
    INTEGER :: nqx(3)
    INTEGER, ALLOCATABLE :: temp_index_xk(:), temp_index_sym(:)
    INTEGER, ALLOCATABLE :: temp_index_ikq(:)
    REAL(8), ALLOCATABLE :: temp_xkq(:,:), xk_collect(:,:)
    LOGICAL :: xk_not_found
    REAL(8) :: sxk(3), dxk(3), xk_cryst(3)
    REAL(8) :: dq1, dq2, dq3
    CHARACTER(LEN=6), EXTERNAL :: int_to_char
    !
    CALL start_clock ( 'exx_grid' )
    !
    IF ( PRESENT (reinit) ) THEN
       IF ( reinit ) THEN
          IF (ALLOCATED(xkq_collect))  DEALLOCATE( xkq_collect )
          IF (ALLOCATED(index_xk)   )  DEALLOCATE( index_xk    )
          IF (ALLOCATED(index_sym)  )  DEALLOCATE( index_sym   )
          exx_grid_initialized = .FALSE.
          nkqs = 0
       ENDIF
    ENDIF
    !
    IF (nq1 <= 0) nq1 = nk1
    IF (nq2 <= 0) nq2 = nk2
    IF (nq3 <= 0) nq3 = nk3
    !
    IF (nkstot == nspin_lsda) THEN
      nq1=1; nq2=1; nq3=1
    ENDIF
    !
    IF (ANY( (/nq1,nq2,nq3/) <=0 )) CALL errore( 'exx_grid_init', "wrong EXX q grid", 1 )
    !
    IF (exx_grid_initialized) CALL errore( 'exx_grid_init', "grid already initialized", 1 )
    exx_grid_initialized = .TRUE.
    !
    ! definitions and checks
    !
    grid_factor = 1._8
    IF (x_gamma_extrapolation) grid_factor = 8.d0/7.d0
    !
    nqs = nq1 * nq2 * nq3
    !
    ! all processors on all pools need to have access to all k+q points
    !
    ALLOCATE( xk_collect(3,nkstot) )
    !
    CALL poolcollect( 3, nks, xk, nkstot, xk_collect )
    !
    ! set a safe limit as the maximum number of auxiliary points we may need
    ! and allocate auxiliary arrays
    max_nk = nkstot * MIN(48, 2 * nsym)
    ALLOCATE( temp_index_xk(max_nk), temp_index_sym(max_nk) )
    ALLOCATE( temp_index_ikq(max_nk) )
    ALLOCATE( temp_xkq(3,max_nk) )
    !
    ! find all k-points equivalent by symmetry to the points in the k-list
    !
    temp_nkqs = 0
    !
    DO isym = 1, nsym
      DO ik = 1, nkstot
          !
          ! go to crystalline coordinates
          xk_cryst(:) = xk_collect(:,ik)
          CALL cryst_to_cart( 1, xk_cryst, at, -1 )
          ! rotate with this sym.op.
          sxk(:) = s(:,1,isym)*xk_cryst(1) + &
                   s(:,2,isym)*xk_cryst(2) + &
                   s(:,3,isym)*xk_cryst(3)
          ! add sxk to the auxiliary list IF it is not already present
          xk_not_found = .TRUE.
          ! *** do-loop skipped the first time because temp_nkqs == 0
          DO ikq = 1, temp_nkqs
            IF (xk_not_found ) THEN
                dxk(:) = sxk(:)-temp_xkq(:,ikq) - NINT(sxk(:)-temp_xkq(:,ikq))
                IF ( ABS(dxk(1))<=eps .AND. &
                     ABS(dxk(2))<=eps .AND. &
                     ABS(dxk(3))<=eps ) xk_not_found = .FALSE.
            ENDIF
          ENDDO
          !
          IF (xk_not_found) THEN
            temp_nkqs                 = temp_nkqs + 1
            temp_xkq(:,temp_nkqs)     = sxk(:)
            temp_index_xk(temp_nkqs)  = ik
            temp_index_sym(temp_nkqs) = isym
          ENDIF
          !
          sxk(:) = - sxk(:)
          xk_not_found = .TRUE.
          DO ikq = 1, temp_nkqs
            IF (xk_not_found ) THEN
                dxk(:) = sxk(:) - temp_xkq(:,ikq) - NINT(sxk(:) - temp_xkq(:,ikq))
                IF ( ABS(dxk(1))<=eps .AND. &
                     ABS(dxk(2))<=eps .AND. &
                     ABS(dxk(3))<=eps ) xk_not_found = .FALSE.
            ENDIF
          ENDDO
          !
          IF (xk_not_found .AND. .NOT. (noncolin.AND.domag) ) THEN
            temp_nkqs                 = temp_nkqs + 1
            temp_xkq(:,temp_nkqs)     = sxk(:)
            temp_index_xk(temp_nkqs)  = ik
            temp_index_sym(temp_nkqs) =-isym
          ENDIF
          !
      ENDDO
    ENDDO
    !
    ! Find good q-point grid. Decrease the nqX until a good grid is found or
    ! until it is 1 x 1 x 1 (always good)
    idx = 1
    sign_ = -1
    nqx = (/nq1, nq2, nq3/)
    DO WHILE (.TRUE.)
      CALL exx_qgrid_init(temp_nkqs, xk_collect, temp_xkq, &
                          nkqs, temp_index_ikq, dxk)

      ! Good q-point mesh
      IF (ALL(ABS(dxk) < eps ) ) THEN
        !
        IF (idx > 1) &
          WRITE(stdout, '(5x,a)') "EXX: WARNING: q-point mesh has been updated!"
        !
        WRITE(stdout, '(5x,a,3i5)') "EXX: q-point mesh: ", nq1, nq2, nq3
        EXIT ! DO WHILE
      ENDIF
      !
      ! Try q-points around the input mesh, prioritizing smaller mesh
      !
      nq1 = nqx(1) + idx * sign_
      nq2 = nqx(2) + idx * sign_
      nq3 = nqx(3) + idx * sign_
      !
      ! Ensure no values smaller than 1
      IF (nq1 < 1) nq1 = 1
      IF (nq2 < 1) nq2 = 1
      IF (nq3 < 1) nq3 = 1
      !
      ! Enforce nqX <= nkX. This is important for surfaces to keep the
      ! Z q-point 1.
      !
      IF (nq1 > nk1) nq1 = nk1
      IF (nq2 > nk2) nq2 = nk2
      IF (nq3 > nk3) nq3 = nk3
      !
      nqs = nq1 * nq2 * nq3
      !
      sign_ = -1 * sign_
      !
      ! Increase idx every other time sign is changed
      IF (sign_ < 0) idx = idx + 1
      !
    ENDDO
    !
    ! allocate and fill the arrays xkq(3,nkqs), index_xk(nkqs) and index_sym(nkqs)
    ! NOTE: nkqs will be redefined as nspin_lsda*nkqs later 
    !
    ALLOCATE( xkq_collect(3,nspin_lsda*nkqs), index_xk(nspin_lsda*nkqs),  &
              index_sym(nspin_lsda*nkqs) )
    !
    DO ik = 1, nkqs
      ikq               = temp_index_ikq(ik)
      xkq_collect(:,ik) = temp_xkq(:,ikq)
      index_xk(ik)      = temp_index_xk(ikq)
      index_sym(ik)     = temp_index_sym(ikq)
    ENDDO
    !
    CALL cryst_to_cart( nkqs, xkq_collect, bg, +1 )
    !
    IF (nkqs > 1) THEN
      WRITE(stdout, '(5x,3a)') "EXX: setup a grid of "//TRIM(int_to_char(nkqs))&
                           //" q-points centered on each k-point"
      IF ( nkqs < 100 .OR. iverbosity > 0 ) THEN
          WRITE( stdout, '(5x,a)' ) '(k+q)-points:'
          DO ik = 1, nkqs
            WRITE( stdout, '(3f12.7,5x,2i5)') (xkq_collect(ikq,ik), ikq=1,3), &
                 index_xk(ik), index_sym(ik)
          ENDDO
      ELSE
          WRITE( stdout, '(5x,a)' ) "(set verbosity='high' to see the list)"
      END IF
    ELSE
      WRITE(stdout, '(5X,"EXX: grid of k+q points same as grid of k-points")')
    ENDIF
    !
    ! if nspin == 2, the kpoints are repeated in couples (spin up, spin down)
    IF (nspin_lsda == 2) THEN
      DO ik = 1, nkstot/2
          DO iq = 1, nqs
            index_xkq(nkstot/2+ik,iq) = index_xkq(ik,iq) + nkqs
          ENDDO
      ENDDO
      !
      DO ikq = 1, nkqs
          xkq_collect(:,ikq+nkqs) = xkq_collect(:,ikq)
          index_xk(ikq + nkqs)  = index_xk(ikq) + nkstot/2
          index_sym(ikq + nkqs) = index_sym(ikq)
      ENDDO
      nkqs = 2 * nkqs
    ENDIF
    !
    ! clean up
    DEALLOCATE( temp_index_xk, temp_index_sym, temp_index_ikq, temp_xkq )
    !
    ! check that everything is what it should be
    CALL exx_grid_check( xk_collect(:,:) )
    DEALLOCATE( xk_collect )
    !
    ! qnorm = max |q|, used to compute the maximum size of interpolation
    !         tables (tab_beta, tab_qrad, etc.) - needed for US/PAW+EXX
    !
    qnorm = 0.0_8
    DO iq = 1, nkqs
       DO ik = 1, nks
          qnorm = MAX(qnorm, SQRT( SUM((xk(:,ik)-xkq_collect(:,iq))**2) ))
       ENDDO
    ENDDO
    qnorm = qnorm * tpiba
    !
    CALL stop_clock( 'exx_grid' )
    !
    RETURN
    !
  END SUBROUTINE exx_grid_init
  !
  !
  !------------------------------------------------------------------------
  SUBROUTINE exx_qgrid_init(temp_nkqs, xk_collect, temp_xkq, nkqs, temp_index_ikq, dxk)
    !------------------------------------------------------------------------
    !! Generate q-point mesh compatible with the k-point mesh
    !
    USE klist,     ONLY : nkstot, xk
    USE cell_base, ONLY : at
    USE symm_base, ONLY : nsym
    !
    IMPLICIT NONE
    INTEGER, INTENT (IN) :: temp_nkqs
    REAL(8), INTENT(IN) :: xk_collect(:,:), temp_xkq(:,:)
    !
    REAL(8), INTENT (OUT) :: dxk(:)
    INTEGER, INTENT (OUT) :: temp_index_ikq(:), nkqs
    !
    INTEGER :: ik, ikq, iq, iq1, iq2, iq3, j, max_nk
    INTEGER, ALLOCATABLE :: new_ikq(:)
    REAL(8) :: sxk(3), xk_cryst(3), dq1, dq2, dq3
    LOGICAL :: xk_not_found
    !
    max_nk = nkstot * MIN(48, 2 * nsym)
    ALLOCATE( new_ikq(max_nk) )

    IF ( ALLOCATED(index_xkq) ) DEALLOCATE( index_xkq )
    ALLOCATE( index_xkq(nkstot, nqs) )
    !
    nkqs = 0
    new_ikq(:) = 0
    !
    ! define the q-mesh step-sizes
    !
    dq1 = 1._8 / DBLE(nq1)
    dq2 = 1._8 / DBLE(nq2)
    dq3 = 1._8 / DBLE(nq3)
    !
    DO ik = 1, nkstot
      ! go to crystalline coordinates
      xk_cryst(:) = xk_collect(:,ik)
      CALL cryst_to_cart( 1, xk_cryst, at, -1 )
      !
      iq = 0
      !
      DO iq1 = 1, nq1
        sxk(1) = xk_cryst(1) + (iq1-1) * dq1
        DO iq2 = 1, nq2
          sxk(2) = xk_cryst(2) + (iq2-1) * dq2
          DO iq3 = 1, nq3
              sxk(3) = xk_cryst(3) + (iq3-1) * dq3
              iq = iq + 1
              xk_not_found = .TRUE.
              !
              DO ikq = 1, temp_nkqs
                IF ( xk_not_found ) THEN
                    dxk(:) = sxk(:)-temp_xkq(:,ikq) - NINT(sxk(:)-temp_xkq(:,ikq))
                    IF ( ALL(ABS(dxk) < eps ) ) THEN
                        xk_not_found = .FALSE.
                        IF ( new_ikq(ikq) == 0) THEN
                            nkqs = nkqs + 1
                            temp_index_ikq(nkqs) = ikq
                            new_ikq(ikq) = nkqs
                        ENDIF
                        index_xkq(ik,iq) = new_ikq(ikq)
                    ENDIF
                ENDIF
              ENDDO ! ikq
              !
              IF (xk_not_found) THEN
                DEALLOCATE( new_ikq )
                RETURN
              ENDIF
              !
          ENDDO
        ENDDO
      ENDDO
      !
    ENDDO
    !
    DEALLOCATE( new_ikq )
  END SUBROUTINE exx_qgrid_init
  !
  !
  !------------------------------------------------------------------------
  SUBROUTINE exx_div_check()
    !------------------------------------------------------------------------
    !! EXX singularity treatment.
    !
    USE cell_base,  ONLY : at, alat
    USE xc_lib,     ONLY : get_screening_parameter
    !
    IMPLICIT NONE
    !
    REAL(8) :: atws(3,3)
    CHARACTER(13) :: sub_name='exx_div_check'
    !
    SELECT CASE ( TRIM(exxdiv_treatment) )
    CASE ( "gygi-baldereschi", "gygi-bald", "g-b", "gb" )
      !
      use_regularization = .TRUE.
      !
    CASE ( "vcut_ws" )
      !
      use_regularization = .TRUE.
      use_coulomb_vcut_ws = .TRUE.
      IF ( x_gamma_extrapolation ) &
            CALL errore( sub_name, 'cannot USE x_gamm_extrap and vcut_ws', 1 )
      !
    CASE ( "vcut_spherical" )
      !
      use_regularization = .TRUE.
      use_coulomb_vcut_spheric = .TRUE.
      IF ( x_gamma_extrapolation ) &
            CALL errore( sub_name, 'cannot USE x_gamm_extrap and vcut_spherical', 1 )
      !
    CASE ( "none" )
      use_regularization = .FALSE.
      !
    CASE DEFAULT
      CALL errore( sub_name, 'invalid exxdiv_treatment: '//TRIM(exxdiv_treatment), 1 )
      !
    END SELECT
    !
    ! Set variables for Coulomb vcut
    ! NOTE: some memory is allocated inside this routine (in variable vcut)
    !       and should be deallocated at the end of the run
    !
    IF ( use_coulomb_vcut_ws .OR. use_coulomb_vcut_spheric ) THEN
       !
       ! build the superperiodicity direct lattice
       !
       atws = alat * at
       !
       atws(:,1) = atws(:,1) * nq1
       atws(:,2) = atws(:,2) * nq2
       atws(:,3) = atws(:,3) * nq3
       !
       CALL vcut_init( vcut, atws, ecutvcut )
       !
       IF (ionode) CALL vcut_info( stdout, vcut )
       !
    ENDIF
    !
    RETURN
    !
  END SUBROUTINE exx_div_check
  !
  !
  !------------------------------------------------------------------------
  SUBROUTINE exx_grid_check( xk_collect )
    !------------------------------------------------------------------------
    !
    USE symm_base,  ONLY : s
    USE cell_base,  ONLY : at
    USE klist,      ONLY : nkstot, xk
    !
    IMPLICIT NONE
    !
    REAL(8), INTENT(IN) :: xk_collect(:,:) 
    !!
    !
    ! ... local variables
    !
    REAL(8) :: sxk(3), dxk(3), xk_cryst(3), xkk_cryst(3)
    INTEGER :: iq1, iq2, iq3, isym, ik, ikk, ikq, iq
    REAL(8) :: dq1, dq2, dq3
    !
    dq1 = 1._8/DBLE(nq1)
    dq2 = 1._8/DBLE(nq2)
    dq3 = 1._8/DBLE(nq3)
    !
    DO ik = 1, nkstot
      xk_cryst(:) = xk_collect(:,ik)
      CALL cryst_to_cart( 1, xk_cryst, at, -1 )
      !
      iq = 0
      DO iq1=1, nq1
        sxk(1) = xk_cryst(1) + (iq1-1) * dq1
        DO iq2 =1, nq2
          sxk(2) = xk_cryst(2) + (iq2-1) * dq2
          DO iq3 =1, nq3
              sxk(3) = xk_cryst(3) + (iq3-1) * dq3
              iq = iq + 1
              !
              ikq  = index_xkq(ik,iq)
              ikk  = index_xk(ikq)
              isym = index_sym(ikq)
              !
              xkk_cryst(:) = at(1,:)*xk_collect(1,ikk) + &
                             at(2,:)*xk_collect(2,ikk) + &
                             at(3,:)*xk_collect(3,ikk)
              IF (isym < 0 ) xkk_cryst(:) = - xkk_cryst(:)
              isym = ABS(isym)
              dxk(:) = s(:,1,isym)*xkk_cryst(1) + &
                       s(:,2,isym)*xkk_cryst(2) + &
                       s(:,3,isym)*xkk_cryst(3) - sxk(:)
              dxk(:) = dxk(:) - NINT(dxk(:))
              IF ( .NOT. ( ABS(dxk(1)) <= eps .AND. &
                           ABS(dxk(2)) <= eps .AND. &
                           ABS(dxk(3)) <= eps )   ) THEN
                  WRITE(*,*) ik,iq
                  WRITE(*,*) ikq,ikk,isym
                  WRITE(*,*) dxk(:)
                  CALL errore( 'exx_grid_check', 'something wrong', 1 )
              ENDIF
              !
          ENDDO
        ENDDO
      ENDDO
    ENDDO
    !
    RETURN
    !
    !
  END SUBROUTINE exx_grid_check
  !
  !
  !-----------------------------------------------------------------------
  SUBROUTINE exx_set_symm( nr1, nr2, nr3, nr1x, nr2x, nr3x )
    !-----------------------------------------------------------------------
    !! Uses \(\text{nkqs}\) and \(\text{index_sym}\) from module \(\texttt{exx}\),
    !! computes \(\text{rir}\).
    !
    USE symm_base,  ONLY : nsym, s, ft
    !
    IMPLICIT NONE
    !
    INTEGER, INTENT(IN) :: nr1, nr2, nr3, nr1x, nr2x, nr3x 
    !
    ! ... local variables
    !
    INTEGER :: ikq, isym, i,j,k, ri,rj,rk, ir, nxxs
    INTEGER, allocatable :: ftau(:,:), s_scaled(:,:,:)
    !
    nxxs = nr1x*nr2x*nr3x
    !
    IF (.NOT. ALLOCATED(rir)) THEN   
        ALLOCATE( rir(nxxs,nsym) )
    ELSEIF ((SIZE(rir,1) /= nxxs) ) THEN 
        DEALLOCATE( rir )
        ALLOCATE( rir(nxxs,nsym) )
    ENDIF
    !
    rir = 0
    ALLOCATE ( ftau(3,nsym), s_scaled(3,3,nsym) )
    CALL scale_sym_ops (nsym, s, ft, nr1, nr2, nr3, s_scaled, ftau)
    DO isym = 1, nsym
       DO k = 1, nr3
          DO j = 1, nr2
             DO i = 1, nr1
                CALL rotate_grid_point( s_scaled(1,1,isym), ftau(1,isym), &
                     i, j, k, nr1, nr2, nr3, ri, rj, rk )
                ir = i + (j-1)*nr1x + (k-1)*nr1x*nr2x
                rir(ir,isym) = ri + (rj-1)*nr1x + (rk-1)*nr1x*nr2x
             ENDDO
          ENDDO
       ENDDO
    ENDDO
    !
    DEALLOCATE ( s_scaled, ftau )
    !
  END SUBROUTINE exx_set_symm
  !
  !-----------------------------------------------------------------------
  SUBROUTINE g2_convolution( ngm, g, xk, xkq, fac )
    !-----------------------------------------------------------------------
    !! This routine calculates the 1/|r-r'| part of the exact exchange
    !! expression in reciprocal space (the G^-2 factor).
    !! It then regularizes it according to the specified recipe.
    !
    USE kinds,      ONLY : DP
    USE cell_base,  ONLY : tpiba, at, tpiba2
    USE constants,  ONLY : fpi, e2, pi
    !
    IMPLICIT NONE
    !
    INTEGER,  INTENT(IN) :: ngm
    !! Number of G vectors
    REAL(8), INTENT(IN) :: g(3,ngm)
    !! Cartesian components of G vectors
    REAL(8), INTENT(IN) :: xk(3)
    !! current k vector
    REAL(8), INTENT(IN) :: xkq(3)
    !! current q vector
    REAL(8), INTENT(INOUT) :: fac(ngm)
    !! Calculated convolution
    !
    ! ... local variables
    !
    INTEGER :: ig !Counters
    REAL(8) :: q(3), qq, x
    REAL(8) :: grid_factor_track(ngm), qq_track(ngm)
    REAL(8) :: nqhalf_dble(3)
    LOGICAL :: odg(3)
    !
    ! ... First the types of Coulomb potential that need q(3) and an external call
    IF( use_coulomb_vcut_ws ) THEN
       DO ig = 1, ngm
          q(:)= ( xk(:) - xkq(:) + g(:,ig) ) * tpiba
          fac(ig) = vcut_get(vcut,q)
       ENDDO
       RETURN
    ENDIF
    !
    IF ( use_coulomb_vcut_spheric ) THEN
       DO ig = 1, ngm
          q(:)= ( xk(:) - xkq(:) + g(:,ig) ) * tpiba
          fac(ig) = vcut_spheric_get(vcut,q)
       ENDDO
       RETURN
    ENDIF
    !
    ! Now the Coulomb potential that are computed on the fly
    !
    nqhalf_dble(1:3) = (/ DBLE(nq1)*0.5_8, DBLE(nq2)*0.5_8, DBLE(nq3)*0.5_8 /)
    !
    ! Set the grid_factor_track and qq_track
    !
    IF ( x_gamma_extrapolation ) THEN
       DO ig = 1, ngm
          q(:)= xk(:) - xkq(:) + g(:,ig)
          qq_track(ig) = SUM(q(:)**2) * tpiba2
          x = (q(1)*at(1,1)+q(2)*at(2,1)+q(3)*at(3,1))*nqhalf_dble(1)
          odg(1) = ABS(x-NINT(x)) < eps
          x = (q(1)*at(1,2)+q(2)*at(2,2)+q(3)*at(3,2))*nqhalf_dble(2)
          odg(2) = ABS(x-NINT(x)) < eps
          x = (q(1)*at(1,3)+q(2)*at(2,3)+q(3)*at(3,3))*nqhalf_dble(3)
          odg(3) = ABS(x-NINT(x)) < eps
          IF( ALL( odg(:) ) ) THEN
             grid_factor_track(ig) = 0._8 ! on double grid
          ELSE
             grid_factor_track(ig) = grid_factor ! not on double grid
          ENDIF
       ENDDO
    ELSE
       DO ig = 1, ngm
          q(:) = xk(:) - xkq(:) + g(:,ig)
          qq_track(ig) = SUM(q(:)**2) * tpiba2
       ENDDO
       grid_factor_track = 1._8
    ENDIF
    !
    ! ... The big loop
    !
    DO ig = 1, ngm
      !
      qq = qq_track(ig)
      !
      IF(gau_scrlen > 0) THEN
         fac(ig) = e2*((pi/gau_scrlen)**(1.5_8))*EXP(-qq/4._8/gau_scrlen) * grid_factor_track(ig)
         !
      ELSEIF (qq > eps_qdiv) THEN
         !
         IF ( erfc_scrlen > 0  ) THEN
            fac(ig) = e2*fpi/qq*(1._8-EXP(-qq/4._8/erfc_scrlen**2)) * grid_factor_track(ig)
         ELSEIF( erf_scrlen > 0 ) THEN
            fac(ig) = e2*fpi/qq*(EXP(-qq/4._8/erf_scrlen**2)) * grid_factor_track(ig)
         ELSE
            fac(ig) = e2*fpi/( qq + yukawa ) * grid_factor_track(ig) ! as HARTREE
         ENDIF
         !
      ELSE
         !
         fac(ig) = - exxdiv ! or rather something ELSE (see F.Gygi)
         !
         IF (yukawa>0._8 .AND. .NOT.x_gamma_extrapolation) fac(ig) = fac(ig) + &
                                                            e2*fpi/( qq + yukawa )
         !
         IF (erfc_scrlen>0._8 .AND. .NOT.x_gamma_extrapolation) fac(ig) = fac(ig) + &
                                                                  e2*pi/(erfc_scrlen**2)
         !
      ENDIF
      !
    ENDDO
    !
  END SUBROUTINE g2_convolution
  !
  !
  !-----------------------------------------------------------------------
  FUNCTION exx_divergence()
     !-----------------------------------------------------------------------
     !
     USE constants,      ONLY : fpi, e2, pi
     USE cell_base,      ONLY : bg, at, alat, omega
     USE gvect,          ONLY : ngm, g
     USE gvecw,          ONLY : gcutw
     USE mp_exx,         ONLY : intra_egrp_comm
     USE mp,             ONLY : mp_sum
     !
     IMPLICIT NONE
     !
     REAL(8) :: exx_divergence
     !
     ! ... local variables
     !
     INTEGER :: iq1,iq2,iq3, ig
     REAL(8) :: div, dq1, dq2, dq3, xq(3), q_, qq, &
                 tpiba2, alpha, x, q(3)
     INTEGER :: nqq, iq
     REAL(8) :: aa, dq
     !
     CALL start_clock( 'exx_div' )
     !
     tpiba2 = (fpi / 2.d0 / alat)**2
     !
     alpha  = 10._8 / gcutw
     !
     IF ( .NOT. use_regularization ) THEN
        exx_divergence = 0._8
        RETURN
     ENDIF
     !
     dq1 = 1._8 / DBLE(nq1)
     dq2 = 1._8 / DBLE(nq2) 
     dq3 = 1._8 / DBLE(nq3) 
     !
     div = 0._8
     !
     DO iq1 = 1, nq1
        DO iq2 = 1, nq2
           DO iq3 = 1, nq3
              xq(:) = bg(:,1) * (iq1-1) * dq1 + &
                      bg(:,2) * (iq2-1) * dq2 + &
                      bg(:,3) * (iq3-1) * dq3
              !
              DO ig = 1, ngm
                 !
                 q(1) = xq(1) + g(1,ig)
                 q(2) = xq(2) + g(2,ig)
                 q(3) = xq(3) + g(3,ig)
                 qq = ( q(1)**2 + q(2)**2 + q(3)**2 )
                 !
                 IF (x_gamma_extrapolation) THEN
                    on_double_grid = .TRUE.
                    x = 0.5d0*(q(1)*at(1,1)+q(2)*at(2,1)+q(3)*at(3,1))*nq1
                    on_double_grid = on_double_grid .AND. (ABS(x-NINT(x))<eps)
                    x = 0.5d0*(q(1)*at(1,2)+q(2)*at(2,2)+q(3)*at(3,2))*nq2
                    on_double_grid = on_double_grid .AND. (ABS(x-NINT(x))<eps)
                    x = 0.5d0*(q(1)*at(1,3)+q(2)*at(2,3)+q(3)*at(3,3))*nq3
                    on_double_grid = on_double_grid .AND. (ABS(x-NINT(x))<eps)
                 ENDIF
                 !
                 IF (.NOT.on_double_grid) THEN
                    IF ( qq > 1.d-8 ) THEN
                       IF ( erfc_scrlen > 0 ) THEN
                          div = div + EXP( -alpha * qq) / qq * &
                                (1._8-EXP(-qq*tpiba2/4.d0/erfc_scrlen**2)) * grid_factor
                       ELSEIF ( erf_scrlen >0 ) THEN
                          div = div + EXP( -alpha * qq) / qq * &
                                (EXP(-qq*tpiba2/4.d0/erf_scrlen**2)) * grid_factor
                       ELSE

                          div = div + EXP( -alpha * qq) / (qq + yukawa/tpiba2) &
                                                     * grid_factor
                       ENDIF
                    ENDIF
                 ENDIF
                 !
              ENDDO
              !
           ENDDO
        ENDDO
     ENDDO
     !
     CALL mp_sum( div, intra_egrp_comm )
     !
     IF (gamma_only) THEN
        div = 2.d0 * div
     ENDIF
     !
     IF ( .NOT. x_gamma_extrapolation ) THEN
        IF ( yukawa > 0._8) THEN
           div = div + tpiba2/yukawa
        ELSEIF( erfc_scrlen > 0._8 ) THEN
           div = div + tpiba2/4.d0/erfc_scrlen**2
        ELSE
           div = div - alpha
        ENDIF
     ENDIF
     !
     div = div * e2 * fpi / tpiba2 / nqs
     !
     alpha = alpha / tpiba2
     !
     nqq = 100000
     dq = 5.0d0 / SQRT(alpha) / nqq
     aa = 0._8
     !
     DO iq = 0, nqq
        q_ = dq * (iq+0.5d0)
        qq = q_ * q_
        IF ( erfc_scrlen > 0 ) THEN
           aa = aa  -EXP( -alpha * qq) * EXP(-qq/4.d0/erfc_scrlen**2)*dq
        ELSEIF ( erf_scrlen > 0 ) THEN
           aa = 0._8
        ELSE
           aa = aa - EXP( -alpha * qq) * yukawa / (qq + yukawa)*dq
        ENDIF
     ENDDO
     !
     aa = aa * 8.d0/fpi
     aa = aa + 1._8/SQRT(alpha*0.25d0*fpi)
     IF ( erf_scrlen > 0) aa = 1._8/SQRT((alpha+1._8/4.d0/erf_scrlen**2)*0.25d0*fpi)
     div = div - e2*omega * aa
     !
     exx_divergence = div * nqs
     !
     CALL stop_clock( 'exx_div' )
     !
     RETURN
     !
  END FUNCTION exx_divergence
  !
  !
END MODULE exx_base
!# 1 "clib_wrappers.f90"
!# 1 "<built-in>"
!# 1 "<command-line>"
!# 1 "/workspace/q-e/UtilXlib//"
!# 1 "clib_wrappers.f90"
!
! Copyright (C) 2004-2013 Quantum ESPRESSO group
! This file is distributed under the terms of the
! GNU General Public License. See the file `License'
! in the root directory of the present distribution,
! or http://www.gnu.org/copyleft/gpl.txt .
!
!--------------------------------------------------------------------------
MODULE clib_wrappers
  !------------------------------------------------------------------------
  !! This module contains fortran wrappers to POSIX system calls.  
  !! The wrappers are used to convert the Fortran CHARACTER array to
  !! null-terminated C *char. The conversion and the interface is done
  !! with the F95 intrinsic \(\texttt{iso_c_binding}\) module.  
  !! Additionally, it provides interfaces to the C functions in clib/: 
  !! \(\texttt{eval_infix, md5_from_file, f_mkdir_safe}\)
  !
  ! NOTE: the mkdir function is NOT called directly as it returns error if
  !       directory already exists. We use instead a C wrapper c_mkdir_safe
  !
  USE util_param, ONLY : DP
  USE ISO_C_BINDING
  IMPLICIT NONE
  !
  ! C std library functions fortran wrappers:
  PUBLIC  f_remove, f_rename, f_chdir, f_mkdir, f_rmdir, f_getcwd
  ! more stuff:
  PUBLIC  f_copy, feval_infix, md5_from_file, f_mkdir_safe, memstat, get_mem_usage, get_mem_avail
  !
  ! HELP:
  ! integer f_remove(pathname)
  ! integer f_rename(oldfile, newfile)
  ! integer f_chdir(newdir)
  ! integer f_chmod(mode) i.e. mode=777 (disable)
  ! integer f_mkdir(dirname, mode) mode is optional
  ! integer f_rmdir(dirname)
  ! subroutine f_getcwd(dirname) 
  ! All "*name" are fortran characters of implicit length,
  ! "mode" are integers, all functions return 0 if successful, -1 otherwise
  !
  ! real(dp) :: result = feval_infix(integer:: ierr, character(len=*) :: expression)
  ! subroutine md5_from_file(character(len=*) :: filename, character(len=32) ::md5)
  PRIVATE
  !
  SAVE
  !
  ! Interfaces to the C functions, these are kept private as Fortran
  ! characters have (?) to be converted explicitly to C character arrays.
  ! Use the f_* wrappers instead
  INTERFACE
    FUNCTION remove(pathname) BIND(C,name="remove") RESULT(r)
      USE iso_c_binding
      CHARACTER(kind=c_char),INTENT(in)  :: pathname(*)
      INTEGER(c_int)        :: r
    END FUNCTION
    FUNCTION rename(input,output) BIND(C,name="rename") RESULT(r)
      USE iso_c_binding
      CHARACTER(kind=c_char),INTENT(in) :: input(*)
      CHARACTER(kind=c_char),INTENT(in) :: output(*)
      INTEGER(c_int)        :: r
    END FUNCTION
    FUNCTION chmod(filename,mode) BIND(C,name="chmod") RESULT(r)
      USE iso_c_binding
      CHARACTER(kind=c_char),INTENT(in)  :: filename(*)
      INTEGER(c_int),VALUE  ,INTENT(in)  :: mode
      INTEGER(c_int)        :: r
    END FUNCTION
    FUNCTION chdir(filename) BIND(C,name="chdir") RESULT(r)
      USE iso_c_binding
      CHARACTER(kind=c_char),INTENT(in)  :: filename(*)
      INTEGER(c_int)        :: r
    END FUNCTION
    FUNCTION mkdir(dirname,mode) BIND(C,name="mkdir") RESULT(r)
      USE iso_c_binding
      CHARACTER(kind=c_char),INTENT(in)  :: dirname(*)
      INTEGER(c_int),VALUE  ,INTENT(in)  :: mode
      INTEGER(c_int)        :: r
    END FUNCTION
    FUNCTION rmdir(dirname) BIND(C,name="rmdir") RESULT(r)
      USE iso_c_binding
      CHARACTER(kind=c_char),INTENT(in)  :: dirname(*)
      INTEGER(c_int)        :: r
    END FUNCTION
    FUNCTION getcwd(buffer,size) BIND(C,name="getcwd") RESULT(r)
      USE iso_c_binding
      CHARACTER(kind=c_char) ,INTENT(out) :: buffer(*)
      INTEGER(c_size_t),VALUE,INTENT(in)  :: size
      TYPE(c_ptr)  :: r
    END FUNCTION
  END INTERFACE
  !
  ! ====================================================================
CONTAINS
  ! ====================================================================
  ! fortran wrappers functions that call the C functions after converting
  ! fortran characters to C character arrays
  FUNCTION f_remove(filename) RESULT(r)
    CHARACTER(*),INTENT(in)  :: filename
    INTEGER(c_int) :: r
    r= remove(TRIM(filename)//C_NULL_CHAR)
  END FUNCTION

  FUNCTION f_rename(input,output) RESULT(k)
    CHARACTER(*),INTENT(in)  :: input,output
    INTEGER :: k
    k= rename(TRIM(input)//C_NULL_CHAR,TRIM(output)//C_NULL_CHAR)
  END FUNCTION

  FUNCTION f_chdir(dirname) RESULT(r)
    CHARACTER(*),INTENT(in)  :: dirname
    INTEGER(c_int) :: r
    r= chdir(TRIM(dirname)//C_NULL_CHAR)
  END FUNCTION
  !
  ! f_mkdir, causes an ERROR if dirname already exists: use f_mkdir_safe instead
  FUNCTION f_mkdir(dirname, mode) RESULT(r)
    CHARACTER(*),INTENT(in)  :: dirname
    INTEGER,INTENT(in) :: mode
    INTEGER(c_int) :: r
    INTEGER(c_int) :: c_mode
    c_mode = INT(mode, kind=c_int)
    r= mkdir(TRIM(dirname)//C_NULL_CHAR, c_mode)
  END FUNCTION
  ! Note: permissions are usually in octal, e.g.:
  !       mode = o'640' => rw-r-----
  FUNCTION f_chmod(filename, mode) RESULT(r)
    CHARACTER(*),INTENT(in)  :: filename
    INTEGER,INTENT(in) :: mode
    INTEGER(c_int) :: r
    INTEGER(c_int) :: c_mode
    c_mode = INT(mode, kind=c_int)
    r= chmod(TRIM(filename)//C_NULL_CHAR, c_mode)
  END FUNCTION

  FUNCTION f_rmdir(dirname) RESULT(r)
    CHARACTER(*),INTENT(in)  :: dirname
    INTEGER(c_int) :: r
    r= rmdir(TRIM(dirname)//C_NULL_CHAR)
  END FUNCTION
  
  SUBROUTINE f_getcwd(output)
    CHARACTER(kind=c_char,len=*),INTENT(out) :: output
    TYPE(c_ptr) :: buffer
    INTEGER(C_SIZE_T) :: length,i  ! was kind=C_LONG, which fails on WIN32
    length=LEN(output)
    buffer=getcwd(output,length)
    DO i=1,length
      IF(output(i:i) == C_NULL_CHAR) EXIT
    ENDDO
    output(i:)=' '
  END SUBROUTINE
  ! ==================================================================== 
  ! copy a file, uses clibs/copy.c which currently does a binary copy
  ! using an 8kb buffer
  ! 
  ! returns:
  !  0 : no error
  ! -1 : cannot open source
  ! -2 : cannot open dest
  ! -3 : error while writing
  ! -4 : disk full while writing
  FUNCTION f_copy(source, dest) RESULT(r)
    INTERFACE
    FUNCTION c_copy(source,dest) BIND(C,name="copy") RESULT(r)
      USE iso_c_binding
      CHARACTER(kind=c_char),INTENT(in)  :: source(*), dest(*)
      INTEGER(c_int)         :: r
    END FUNCTION c_copy
    END INTERFACE
    CHARACTER(*),INTENT(in)  :: source, dest
    INTEGER(c_int) :: r
    r= c_copy(TRIM(source)//C_NULL_CHAR, TRIM(dest)//C_NULL_CHAR)
  END FUNCTION
  !
  ! safe mkdir from clib/c_mkdir.c that creates a directory, if necessary, 
  ! and checks permissions. It can be called in parallel.
  ! Returns: 0 = all ok
  !          1 = error
  !         -1 = the directory already existed and is properly writable
  FUNCTION f_mkdir_safe(dirname) RESULT(r)
    INTERFACE
    FUNCTION mkdir_safe(dirname) BIND(C,name="c_mkdir_safe") RESULT(r)
      USE iso_c_binding
      CHARACTER(kind=c_char),INTENT(in)  :: dirname(*)
      INTEGER(c_int)         :: r
    END FUNCTION mkdir_safe
    END INTERFACE
    CHARACTER(*),INTENT(in)  :: dirname
    INTEGER(c_int) :: r
    r= mkdir_safe(TRIM(dirname)//C_NULL_CHAR)
  END FUNCTION
  !
  ! Two more wrappers for eval_infix (simple algebric expression parser)
  ! and for get_md5 which computes the md5 sum of a file.
  !
  FUNCTION feval_infix(fierr, fstr)
    USE ISO_C_BINDING
    IMPLICIT NONE
    REAL(8) :: feval_infix
    INTEGER :: fierr
    CHARACTER(len=*) :: fstr
    INTEGER :: filen
    !
    INTERFACE
    FUNCTION ceval_infix(cierr, cstr, cilen) BIND(C, name="eval_infix")
    !REAL(kind=c_double) FUNCTION ceval_infix(cierr, cstr, cilen) BIND(C, name="eval_infix")
    !  double eval_infix( int *ierr, const char *strExpression, int len )
      USE ISO_C_BINDING
      REAL(kind=c_double) :: ceval_infix
      INTEGER(kind=c_int)    :: cierr
      CHARACTER(kind=c_char) :: cstr(*)
      INTEGER(kind=c_int),VALUE :: cilen
    END FUNCTION ceval_infix
    END INTERFACE
    !
    INTEGER(kind=c_int) :: cierr
    INTEGER(kind=c_int) :: cilen
    CHARACTER(len=len_trim(fstr)+1,kind=c_char) :: cstr
    !
    INTEGER :: i
    !
    filen = len_trim(fstr)
    cilen = INT(filen, kind=c_int)
    DO i = 1,filen
      cstr(i:i) = fstr(i:i)
    ENDDO
    cstr(filen+1:filen+1)=C_NULL_CHAR
    !
    feval_infix = REAL( ceval_infix(cierr, cstr, cilen), kind=8)
    fierr = INT(cierr)
    RETURN
  END FUNCTION feval_infix
  !
  !
  SUBROUTINE md5_from_file (ffile, fmd5)
    IMPLICIT NONE
    CHARACTER(LEN=*), INTENT (IN) :: ffile
    CHARACTER(len=32), INTENT (OUT) :: fmd5
    !
    INTERFACE
    SUBROUTINE cget_md5(cfile, cmd5, cierr) BIND(C, name="get_md5")
    ! void get_md5(const char *file, char *md5, int err)
      USE ISO_C_BINDING
      CHARACTER(kind=c_char) :: cfile(*)
      CHARACTER(kind=c_char) :: cmd5(*)
      INTEGER(kind=c_int)    :: cierr
    END SUBROUTINE cget_md5
    END INTERFACE
    !
    INTEGER,PARAMETER :: md5_length = 32
    INTEGER :: i
    !
    CHARACTER(len=len_trim(ffile)+1,kind=c_char) :: cfile!(*)
    CHARACTER(len=(md5_length+1),kind=c_char)    :: cmd5!(*)
    INTEGER(kind=c_int)    :: cierr
    !
    cfile = TRIM(ffile)//C_NULL_CHAR
    !
    CALL cget_md5(cfile, cmd5, cierr)
    !
    DO i = 1,md5_length
       fmd5(i:i) = cmd5(i:i)
    ENDDO
    !
  END SUBROUTINE md5_from_file
  !
  ! Wrapper for (buggy) C routine "memstat"
  !
  SUBROUTINE memstat (kbytes)
    IMPLICIT NONE
    INTEGER, INTENT(OUT) :: kbytes
    !
    INTERFACE
       FUNCTION c_memstat( ) BIND(C, name="c_memstat")
         USE ISO_C_BINDING
         INTEGER(kind=c_int) :: c_memstat
       END FUNCTION c_memstat
    END INTERFACE
    !
    kbytes = c_memstat()
    !
  END SUBROUTINE memstat
  !
  ! Wrapper for C routine "getMemUsage"
  !
  FUNCTION get_mem_usage() RESULT(kbytes)
    IMPLICIT NONE
    INTEGER(kind=c_size_t) :: kbytes
    !
    INTERFACE
       FUNCTION c_getmemusage() BIND(C, name="c_getMemUsage")
         USE ISO_C_BINDING
         INTEGER(kind=c_size_t) :: c_getmemusage
       END FUNCTION c_getmemusage
    END INTERFACE
    !
    kbytes = c_getmemusage()
    !
  END FUNCTION get_mem_usage
  !
  ! Wrapper for C routine "getMemAvail"
  !
  FUNCTION get_mem_avail() RESULT(kbytes)
    IMPLICIT NONE
    INTEGER(kind=c_size_t) :: kbytes
    !
    INTERFACE
       FUNCTION c_getmemavail() BIND(C, name="c_getMemAvail")
         USE ISO_C_BINDING
         INTEGER(kind=c_size_t) :: c_getmemavail
       END FUNCTION c_getmemavail
    END INTERFACE
    !
    kbytes = c_getmemavail();
    !
  END FUNCTION get_mem_avail
  !
END MODULE
!# 1 "io_files.f90"
!# 1 "<built-in>"
!# 1 "<command-line>"
!# 1 "/workspace/q-e/Modules//"
!# 1 "io_files.f90"
!
! Copyright (C) 2002-2023 Quantum ESPRESSO group
