MODULE upf_params
  
  IMPLICIT NONE
  SAVE

  INTEGER, PARAMETER :: &
       lmaxx  = 4,      &! max non local angular momentum (l=0 to lmaxx)      
       lqmax= 2*lmaxx+1  ! max number of angular momenta of Q

END MODULE upf_params
!# 1 "upf_spinorb.f90"
!# 1 "<built-in>"
!# 1 "<command-line>"
!# 1 "/workspace/q-e/upflib//"
!# 1 "upf_spinorb.f90"
!
! Copyright (C) 2001-2020 Quantum ESPRESSO group
! This file is distributed under the terms of the
! GNU General Public License. See the file `License'
! in the root directory of the present distribution,
! or http://www.gnu.org/copyleft/gpl.txt .
!
!
MODULE upf_spinorb
  !
  !! Variables needed for calculations with spin-orbit
  !
  USE upf_kinds,   ONLY : DP
  USE upf_params,  ONLY : lmaxx, lqmax 
  !
  !! FIXME: rot_ylm could be dynamically allocated
  !
  IMPLICIT NONE
  SAVE

  LOGICAL :: is_spinorbit
  !! if .TRUE. this is a spin-orbit calculation
  !! internal flag, set by uspp_allocate, to be used only in upflib
  COMPLEX (8) :: rot_ylm(lqmax,lqmax)
  !! transform real spherical harmonics into complex ones
  COMPLEX (8), ALLOCATABLE :: fcoef(:,:,:,:,:)
  !! function needed to account for spinors.
  !
  INTERFACE transform_qq_so
     MODULE PROCEDURE transform_qqr_so, transform_qqc_so
  END INTERFACE transform_qq_so
CONTAINS
  !
  !----------------------------------------------------------------------
  SUBROUTINE transform_qqc_so( qq, qq_so )
  !----------------------------------------------------------------------
  ! For Berry-phase / macroscopic electric-field calculations (qq complex)
  !  
  USE uspp_param,   ONLY : nsp, upf, nhm, nh
  !
  COMPLEX(8), INTENT(in)  :: qq(nhm, nhm, nsp)
  COMPLEX(8), INTENT(out) :: qq_so(nhm, nhm, 4, nsp)
  !
  INTEGER :: nt, ih, jh, kh, lh, ijs, is1, is2, is
  !
  qq_so=(0.0_8, 0.0_8)
  DO nt = 1, nsp
    IF ( upf(nt)%tvanp ) THEN
      IF (upf(nt)%has_so) THEN
        DO ih=1,nh(nt)
          DO jh=1,nh(nt)
            DO kh=1,nh(nt)
              DO lh=1,nh(nt)
                ijs=0
                DO is1=1,2
                  DO is2=1,2
                    ijs=ijs+1
                    DO is=1,2
                      qq_so(kh,lh,ijs,nt) = qq_so(kh,lh,ijs,nt)    &
                           + qq(ih,jh,nt) * fcoef(kh,ih,is1,is,nt) &
                                          * fcoef(jh,lh,is,is2,nt)
                    ENDDO
                  ENDDO
                ENDDO
              ENDDO
            ENDDO
          ENDDO
        ENDDO
      ELSE
        DO ih = 1, nh (nt)
          DO jh = ih, nh (nt)
             IF (is_spinorbit) THEN
                 qq_so (ih, jh, 1, nt) = qq (ih, jh, nt) 
                 qq_so (jh, ih, 1, nt) = qq_so (ih, jh, 1, nt)
                 qq_so (ih, jh, 4, nt) = qq_so (ih, jh, 1, nt)
                 qq_so (jh, ih, 4, nt) = qq_so (ih, jh, 4, nt)
             ENDIF
          ENDDO
        ENDDO
      ENDIF
    ENDIF
  ENDDO
  !
END SUBROUTINE transform_qqc_so
  !
  !----------------------------------------------------------------------
  SUBROUTINE transform_qqr_so( qq, qq_so )
  !----------------------------------------------------------------------
  !
  ! For non-Berry-phase/macroscopic electric-field calculations (qq real)
  !
  USE uspp_param,   ONLY : nsp, upf, nhm, nh
  !
  REAL(8), INTENT(in)  :: qq(nhm, nhm, nsp)
  COMPLEX(8), INTENT(out) :: qq_so(nhm, nhm, 4, nsp)
  !
  INTEGER :: nt, ih, jh, kh, lh, ijs, is1, is2, is
  !
  qq_so=(0.0_8, 0.0_8)
  DO nt = 1, nsp
    IF ( upf(nt)%tvanp ) THEN
      IF (upf(nt)%has_so) THEN
        DO ih=1,nh(nt)
          DO jh=1,nh(nt)
            DO kh=1,nh(nt)
              DO lh=1,nh(nt)
                ijs=0
                DO is1=1,2
                  DO is2=1,2
                    ijs=ijs+1
                    DO is=1,2
                      qq_so(kh,lh,ijs,nt) = qq_so(kh,lh,ijs,nt)    &
                           + qq(ih,jh,nt) * fcoef(kh,ih,is1,is,nt) &
                                          * fcoef(jh,lh,is,is2,nt)
                    ENDDO
                  ENDDO
                ENDDO
              ENDDO
            ENDDO
          ENDDO
        ENDDO
      ELSE
        DO ih = 1, nh (nt)
          DO jh = ih, nh (nt)
             IF (is_spinorbit) THEN
                 qq_so (ih, jh, 1, nt) = qq (ih, jh, nt) 
                 qq_so (jh, ih, 1, nt) = qq_so (ih, jh, 1, nt)
                 qq_so (ih, jh, 4, nt) = qq_so (ih, jh, 1, nt)
                 qq_so (jh, ih, 4, nt) = qq_so (ih, jh, 4, nt)
             ENDIF
          ENDDO
        ENDDO
      ENDIF
    ENDIF
  ENDDO

END SUBROUTINE transform_qqr_so

END MODULE upf_spinorb
!# 1 "upf_invmat.f90"
!# 1 "<built-in>"
!# 1 "<command-line>"
!# 1 "/workspace/q-e/upflib//"
!# 1 "upf_invmat.f90"
!
! Copyright (C) 2016 Quantum ESPRESSO group
! This file is distributed under the terms of the
! GNU General Public License. See the file `License'
! in the root directory of the present distribution,
! or http://www.gnu.org/copyleft/gpl.txt .
!
MODULE upf_invmat

  IMPLICIT NONE
  PRIVATE
  PUBLIC :: invmat

CONTAINS

  SUBROUTINE invmat (n, a, a_inv)
  !-----------------------------------------------------------------------
  ! computes the inverse of a n*n real matrix "a" using LAPACK routines 
  ! "a_inv" contains the inverse on output; "a" is unchanged
  !
  USE upf_kinds, ONLY : DP
  IMPLICIT NONE
  INTEGER, INTENT(in) :: n
  REAL(8), DIMENSION (n,n), INTENT(inout)  :: a
  REAL(8), DIMENSION (n,n), INTENT(out)    :: a_inv
  !
  INTEGER :: info, lda, lwork
  ! info=0: inversion was successful
  ! lda   : leading dimension (the same as n)
  INTEGER, ALLOCATABLE :: ipiv (:)
  ! ipiv  : work space for pivoting
  REAL(8), ALLOCATABLE :: work (:)
  ! more work space
  ! INTEGER, SAVE :: lworkfact = 64
  !
  lda = n
  lwork=64*n
  ALLOCATE(ipiv(n), work(lwork) )
  !
  a_inv(:,:) = a(:,:)
  CALL dgetrf (n, n, a_inv, lda, ipiv, info)
  CALL upf_error ('invmat', 'error in DGETRF', abs (info) )
  CALL dgetri (n, a_inv, lda, ipiv, work, lwork, info)
  CALL upf_error ('invmat', 'error in DGETRI', abs (info) )
  !
  ! lworkfact = INT (work(1)/n)
  DEALLOCATE ( work, ipiv )

  END SUBROUTINE invmat

END MODULE upf_invmat
