!
! Tools for Goedecker-Teter-Hutter pseudopotentials
! Contains routine "atmlength", copyright by ABINIT group
!
module m_gth
  use upf_kinds, only: dp
  implicit none
  !
  private
  public :: gth_parameters, readgth, vloc_gth, dvloc_gth, &
       mk_ffnl_gth, mk_dffnl_gth, deallocate_gth
  !
  type gth_parameters
     integer  :: itype, lloc, lmax
     real(8) :: rloc, cc(4)
     integer,  pointer :: lll(:), ipr(:)
     real(8), pointer :: rrl(:)
  end type gth_parameters
  type (gth_parameters), pointer, dimension(:), private, save :: gth_p => null()
  !
contains
  !-----------------------------------------------------------------------
  subroutine mk_ffnl_gth(itype, ibeta, nq, omega, qg, vq)
    !-----------------------------------------------------------------------
    !
    USE upf_kinds,    ONLY: dp
    USE upf_const,    ONLY: pi, fpi, e2
    
    implicit none
    !  
    ! I/O 
    integer,  intent(in)  :: itype, ibeta, nq
    real(8), intent(in)  :: omega
    real(8), intent(in)  :: qg(nq)
    real(8), intent(out) :: vq(nq)
    !     
    ! Local variables
    integer, parameter :: nprj_max(0:3)=[3, 3, 2, 1]
    integer  :: ii, my_gth, ll, iproj
    real(8) :: rrl, qr2, fact
    !
    my_gth=0
    do ii=1,size(gth_p)
       if (gth_p(ii)%itype==itype) then
          my_gth=ii
          exit
       endif
    enddo
    if (my_gth==0) call upf_error('mk_ffnl_gth', 'cannot map itype in some gtp param. set', itype)
    iproj=gth_p(my_gth)%ipr(ibeta)
    ll=gth_p(my_gth)%lll(ibeta)
    rrl=gth_p(my_gth)%rrl(ll)
    if ( ll<0 .or. ll>3  ) call upf_error('mk_ffnl_gth', 'wrong l:', ll)
    if ( iproj>nprj_max(ll) ) call upf_error('mk_ffnl_gth', 'projector exceeds max. n. of projectors', iproj)
    !
    lif: if (ll==0) then     ! s channel
       !
       if(iproj==1)then
          do ii=1,nq
             qr2=(qg(ii)*rrl)**2
             vq(ii)=exp(-0.5_8*qr2)
          end do
       else if(iproj==2)then
          do ii=1,nq
             qr2=(qg(ii)*rrl)**2
             vq(ii)=2._8/sqrt(15._8) * exp(-0.5_8*qr2) * ( 3._8-qr2 )
          end do
       else if(iproj==3)then
          do ii=1,nq
             qr2=(qg(ii)*rrl)**2
             vq(ii)=(4._8/3._8)/sqrt(105._8) * exp(-0.5_8*qr2) * &
                  &         (15._8-10._8*qr2 + qr2**2)
          end do
       end if
       !
    else if (ll==1) then lif ! p channel
       !
       if(iproj==1)then
          do ii=1,nq
             qr2=(qg(ii)*rrl)**2
             vq(ii)=(1._8/sqrt(3._8)) * exp(-0.5_8*qr2) * qg(ii)
          end do
       else if(iproj==2)then
          do ii=1,nq
             qr2=(qg(ii)*rrl)**2
             vq(ii)=(2._8/sqrt(105._8)) * exp(-0.5_8*qr2) * qg(ii)*(5._8-qr2)
          end do
       else if(iproj==3)then
          do ii=1,nq
             qr2=(qg(ii)*rrl)**2
             vq(ii)=(4._8/3._8)/sqrt(1155._8) * exp(-0.5_8*qr2) * &
                  &         qg(ii) * (35._8-14._8*qr2+qr2**2)
          end do
       end if
       !
    else if (ll==2) then lif ! d channel [ ONLY 2 PROJECTORS!! ]
       !
       if(iproj==1)then
          do ii=1,nq
             qr2=(qg(ii)*rrl)**2
             vq(ii)=(1._8/sqrt(15._8)) * exp(-0.5_8*qr2) * qg(ii)**2
          end do
       else if(iproj==2)then
          do ii=1,nq
             qr2=(qg(ii)*rrl)**2
             vq(ii)=(2._8/3._8)/sqrt(105._8) * exp(-0.5_8*qr2) * &
                  &         qg(ii)**2 * (7._8-qr2)
          end do
       end if
       !
    else if (ll==3) then lif ! f channel [ ONLY 1 PROJECTOR!! ]
       !
       do ii=1,nq
          qr2=(qg(ii)*rrl)**2
          vq(ii)=qg(ii)**3 * exp(-0.5_8*qr2) / sqrt(105.0_8)
       end do
       !
    end if lif
    !
    fact = e2 * fpi * pi**0.25_8 * sqrt( 2._8**(ll+1) * rrl**(2*ll+3) / omega )
    vq(:)=fact*vq(:) 
    !
  end subroutine mk_ffnl_gth
  !-----------------------------------------------------------------------
  subroutine mk_dffnl_gth(itype, ibeta, nq, omega, tpiba, qg, dvq)
    !-----------------------------------------------------------------------
    !
    USE upf_kinds,    ONLY: dp
    USE upf_const,    ONLY: pi, fpi, e2

    implicit none
    !  
    ! I/O 
    integer,  intent(in)  :: itype, ibeta, nq
    real(8), intent(in)  :: omega
    real(8), intent(in)  :: tpiba
    real(8), intent(in)  :: qg(nq)
    real(8), intent(out) :: dvq(nq)
    !     
    ! Local variables
    integer, parameter :: nprj_max(0:3)=[3, 3, 2, 1]
    integer  :: ii, my_gth, ll, iproj
    real(8) :: rrl, rl2, qt, q1r2, q3r4, q5r6, qr2, qr4, qr6, fact, e_qr2_h
    !
    my_gth=0
    do ii=1,size(gth_p)
       if (gth_p(ii)%itype==itype) then
          my_gth=ii
          exit
       endif
    enddo
    if (my_gth==0) call upf_error('mk_dffnl_gth', 'cannot map itype in some gtp param. set', itype)
    iproj=gth_p(my_gth)%ipr(ibeta)
    ll=gth_p(my_gth)%lll(ibeta)
    rrl=gth_p(my_gth)%rrl(ll)
    if ( ll<0 .or. ll>3  ) call upf_error('mk_dffnl_gth', 'wrong l:', ll)
    if ( iproj>nprj_max(ll) ) call upf_error('mk_dffnl_gth', 'projector exceeds max. n. of projectors', iproj)
    !
    lif: if (ll==0) then     ! s channel
       !
       if(iproj==1)then
          do ii=1,nq
             qt = sqrt(qg(ii))*tpiba
             rl2= rrl**2
             qr2= qt*qt*rl2
             e_qr2_h=exp(-0.5_8*qr2)
             !
             dvq(ii)=-qt*rl2*e_qr2_h
          end do
       else if(iproj==2)then
          do ii=1,nq
             qt = sqrt(qg(ii))*tpiba
             rl2= rrl**2
             q1r2=qt*rl2
             qr2= qt*q1r2
             q3r4=qr2*q1r2
             e_qr2_h=exp(-0.5_8*qr2)
             !
             dvq(ii)=2._8/sqrt(15._8) * e_qr2_h * (-5._8*q1r2+q3r4)
          end do
       else if(iproj==3)then
          do ii=1,nq
             qt = sqrt(qg(ii))*tpiba
             rl2= rrl**2
             q1r2=qt*rl2
             qr2= qt*q1r2
             q3r4=qr2*q1r2
             q5r6=qr2*q3r4
             e_qr2_h=exp(-0.5_8*qr2)
             !
             dvq(ii)=(4._8/3._8)/sqrt(105._8) * e_qr2_h * (-35._8*q1r2 + 14._8*q3r4 - q5r6)
          end do
       end if
       !
    else if (ll==1) then lif ! p channel
       !
       if(iproj==1)then
          do ii=1,nq
             qt = sqrt(qg(ii))*tpiba
             qr2=(qt*rrl)**2
             e_qr2_h=exp(-0.5_8*qr2)
             !
             dvq(ii)=(1._8/sqrt(3._8)) * e_qr2_h * (1._8 - qr2)
          end do
       else if(iproj==2)then
          do ii=1,nq
             qt = sqrt(qg(ii))*tpiba
             qr2=(qt*rrl)**2
             qr4=qr2**2
             e_qr2_h=exp(-0.5_8*qr2)
             !
             dvq(ii)=(2._8/sqrt(105._8)) * e_qr2_h * (5._8 - 8._8*qr2 + qr4)
          end do
       else if(iproj==3)then
          do ii=1,nq
             qt = sqrt(qg(ii))*tpiba
             qr2=(qt*rrl)**2
             qr4=qr2**2
             qr6=qr4*qr2
             e_qr2_h=exp(-0.5_8*qr2)
             !
             dvq(ii)=(4._8/3._8)/sqrt(1155._8) * e_qr2_h * (35._8 - 77._8*qr2 + 19._8*qr4 - qr6)
          end do
       end if
       !
    else if (ll==2) then lif ! d channel [ ONLY 2 PROJECTORS!! ]
       !
       if(iproj==1)then
          do ii=1,nq
             qt = sqrt(qg(ii))*tpiba
             qr2=(qt*rrl)**2
             e_qr2_h=exp(-0.5_8*qr2)
             !
             dvq(ii)=(1._8/sqrt(15._8)) * e_qr2_h * qt*(2._8 - qr2)
          end do
       else if(iproj==2)then
          do ii=1,nq
             qt = sqrt(qg(ii))*tpiba
             qr2=(qt*rrl)**2
             qr4=qr2**2
             e_qr2_h=exp(-0.5_8*qr2)
             !
             dvq(ii)=(2._8/3._8)/sqrt(105._8) * e_qr2_h * qt*(14._8 - 11._8*qr2 + qr4)
          end do
       end if
       !
    else if (ll==3) then lif ! f channel [ ONLY 1 PROJECTOR!! ]
       !
       do ii=1,nq
          qt = qg(ii)*tpiba**2
          qr2=qt*rrl**2
          e_qr2_h=exp(-0.5_8*qr2)
          !
          dvq(ii)=e_qr2_h * qt*(3._8 - qr2) / sqrt(105.0_8)
       end do
       !
    end if lif
    !
    fact = e2 * fpi * pi**0.25_8 * sqrt( 2._8**(ll+1) * rrl**(2*ll+3) / omega )
    dvq(:)=fact*dvq(:) 
    !
  end subroutine mk_dffnl_gth
  !
!-----------------------------------------------------------------------
subroutine vloc_gth(itype, zion, tpiba2, ngl, gl, omega, vloc)
  !-----------------------------------------------------------------------
  !
  ! compute vloc(G), including the correct G=0 limit, making no assumption
  ! that G=0 is the first vector (so we can compute Vloc(q+G) as well)
  !
  USE upf_kinds, ONLY: dp
  USE upf_const, ONLY: pi, fpi, e2, eps8

  implicit none
  !
  ! I/O
  integer,  intent(in)  :: itype, ngl
  real(8), intent(in)  :: zion, tpiba2, omega, gl (ngl)
  real(8), intent(out) :: vloc (ngl)
  !
  ! Local variables
  integer  :: ii, my_gth, igl, igl0
  real(8) :: cc1, cc2, cc3, cc4, rloc, epsatm, gx2, rq2, rl3, e_rq2h
  !
  ! Find gtp param. set for type itype
  my_gth=0
  do ii=1,size(gth_p)
    if (gth_p(ii)%itype==itype) then
      my_gth=ii
      exit
    endif
  enddo
  if (my_gth==0) call upf_error('vloc_gth', 'cannot map itype in some gth param. set', itype)
  rloc=gth_p(my_gth)%rloc
  cc1=gth_p(my_gth)%cc(1)
  cc2=gth_p(my_gth)%cc(2)
  cc3=gth_p(my_gth)%cc(3)
  cc4=gth_p(my_gth)%cc(4)

  ! Compute epsatm = lim(q->0) [Vloc(q) + zion/(Pi*q^2)]
  epsatm=2._8*pi*rloc**2*zion+(2._8*pi)**(1.5_8)*rloc**3*(cc1+3._8*cc2+15._8*cc3+105._8*cc4)
  ! 1/\Omega * \sum_i epsatm(i) is v_loc(G=0)
  !
  do igl = 1, ngl
     if ( gl(igl) < eps8 ) then
        !   here the G=0 terms
        !   NOTE: not assuming G are ordered
        vloc(igl) = epsatm * e2 / omega
     else
        !   here the G<>0 terms
        gx2    = gl(igl) * tpiba2
        rq2    = gx2*rloc**2
        rl3    = rloc**3
        e_rq2h = exp(-0.5_8*rq2)
        vloc (igl) = &
             fpi * e_rq2h*(-zion/gx2 + sqrt(pi/2._8)*rl3* &
             ( &
             cc1 + &
             cc2*(3._8-rq2) + &
             cc3*(15._8-10._8*rq2+rq2**2) + &
             cc4*(105._8-rq2*(105._8-rq2*(21._8-rq2))) &
             ) &
             )* e2 / omega
     end if
  enddo
  !
end subroutine vloc_gth
!
!-----------------------------------------------------------------------
subroutine dvloc_gth( itype, zion, tpiba2, ngl, gl, omega, dvloc )
  !------------------------------------------------------------------------------
  !! GPU version of 'dvloc_gth' from 'Modules/gth.f90'
  !! dvloc = D Vloc (g^2) / D g^2 = (1/2g) * D Vloc(g) / D g
  !
  USE upf_kinds,    ONLY : DP
  USE upf_const,    ONLY : pi, tpi, e2, eps8
  !
  implicit none
  !
  ! I/O
  integer,  intent(in) :: itype, ngl
  real(8), intent(in) :: zion, tpiba2, omega
  real(8), intent(in) :: gl(ngl)
  real(8), intent(out) :: dvloc(ngl)
  !
  ! Local variables
  integer :: ii, my_gth, igl, igl0
  real(8) :: cc1, cc2, cc3, cc4, rloc, gl1, &
              gx, gx2, gx3, rl2, rl3, rq2, r2q, r4g3, r6g5, e_rq2h, fact
  !
  !
! IF ( do_comp_esm ) call upf_error('vloc_gth', 'ESM not implemented', itype)
  !
  ! Find gtp param. set for type itype
  my_gth = 0
  do ii = 1, SIZE(gth_p)
    if (gth_p(ii)%itype==itype) then
      my_gth = ii
      exit
    endif
  enddo
  !
  IF ( my_gth==0 ) CALL upf_error( 'dvloc_gth', 'cannot map itype in some gtp param. set', itype )
  rloc = gth_p(my_gth)%rloc
  cc1  = gth_p(my_gth)%cc(1)
  cc2  = gth_p(my_gth)%cc(2)
  cc3  = gth_p(my_gth)%cc(3)
  cc4  = gth_p(my_gth)%cc(4)
  !
  ! Compute vloc(q)
  gl1 = gl(1)
  if (gl1 < eps8) then
     !
     ! first the G=0 term
     !
     dvloc(1) = 0.0_8
     igl0 = 2
  else
     igl0 = 1
  endif
  !
  !   here the G<>0 terms, we first compute the part of the integrand 
  !   function independent of |G| in real space
  !
  fact = tpi * e2 / omega
  !
  do igl = igl0, ngl
     gx     = SQRT(gl(igl) * tpiba2)
     gx2    = gx**2
     gx3    = gx*gx2
     rl2    = rloc**2
     rl3    = rloc*rl2
     rq2    = gx2*rl2
     r2q    = gx*rl2
     r4g3   = rl2*rl2*gx3
     r6g5   = r4g3*rl2*gx2
     e_rq2h = EXP(-0.5_8*rq2)
     dvloc(igl) = fact * &
         e_rq2h*(zion*(rq2+2._8)/gx3 + SQRT(pi/2._8)*rl3* &
           ( &
             ( &
               - 2._8*r2q* (cc2+10._8*cc3+105._8*cc4) &
               + 4._8*r4g3*(cc3+21._8*cc4) &
               - 6._8*r6g5* cc4 &
             ) - r2q*( &
               cc1 + &
               cc2*(3._8-rq2) + &
               cc3*(15._8-10._8*rq2+rq2**2) + &
               cc4*(105._8-rq2*(105._8-rq2*(21._8-rq2))) &
             ) &
           ) &
        )/gx 
  enddo
  !
  !
end subroutine dvloc_gth
!-----------------------------------------------------------------------
subroutine deallocate_gth( lflag )
  !-----------------------------------------------------------------------
  !

  implicit none
  !  
  ! I/O 
  logical, intent(in) :: lflag
  !
  ! Local variables
  integer :: ii
  !
  IF ( lflag .and. ASSOCIATED( gth_p ) ) THEN
     DO ii=1, SIZE(gth_p)
        DEALLOCATE ( gth_p(ii)%lll, gth_p(ii)%ipr, gth_p(ii)%rrl )
     ENDDO
     DEALLOCATE( gth_p )
  ENDIF
  !
end subroutine deallocate_gth
!-----------------------------------------------------------------------
subroutine readgth (psfile, np, upf, ierr)
  !-----------------------------------------------------------------------
  !
  USE upf_kinds,    ONLY: dp
  USE upf_io,       ONLY: stdout
  USE upf_const,    ONLY: e2, tpi
  USE upf_params,   ONLY: lmaxx
  USE upf_utils,    ONLY: l_to_spdf
  USE pseudo_types, ONLY: pseudo_upf, reset_upf

  implicit none
  !
  ! I/O
  TYPE (pseudo_upf) :: upf
  character(LEN=*), intent(in) :: psfile
  integer, intent(in) :: np
  integer, intent(out):: ierr
  !
  ! Local variables
  integer  :: iunps, ios, pspdat, pspcod, pspxc, lmax, lloc, mmax, &
              ii, jj, ll, nn, nnonloc, nprl, os, ns, iv, jv
  real(8) :: rcore, qcore, rc2, prefact, znucl, r2well, rloc, rrl, cc(4)
  character(len=256)            :: info
  character(len=  1), parameter :: ch10=char(10)
  character(len=  2), external  :: atom_name
  integer,  allocatable         :: nproj(:)
  real(8), allocatable         :: hij(:,:,:), kij(:,:,:)
  type(gth_parameters), pointer, dimension(:) :: gth_tmp_p
  !
  ierr = 1
  os=0; if (associated(gth_p)) os=size(gth_p)
  ns=os+1; allocate(gth_tmp_p(ns))
  if (os>0) then
    gth_tmp_p(1:os)=gth_p(1:os)
    deallocate(gth_p)
  end if
  nullify(gth_p)
  gth_p=>gth_tmp_p
  nullify(gth_tmp_p)
  gth_p(ns)%itype=np
  !
  CALL reset_upf(upf)
  !
  upf%is_gth=.true.
  upf%is_multiproj=.true.
  upf%generated="GTH norm-conserving PP, generated by Matthias Krack"
  upf%author   ="Goedecker/Hartwigsen/Hutter/Teter/Krack"
  upf%comment  ="GTH analytical, separable"
  upf%rel = 'scalar'
  upf%typ = 'NC'
  ! not sure next three lines should be there: upf%nwcf is set to 0 in reset_upf
  upf%nwfc= 0
  allocate(upf%lchi(upf%nwfc))
  upf%lchi(:) = 0

  open(newunit=iunps, file=psfile, form='formatted', status='old', iostat = ios)
  if ( ios .ne. 0 ) go to 400
  read (iunps, '(a)', end=400, err=400, iostat=ios) info
  read (iunps, *, err=400) znucl, upf%zp, pspdat
  if (upf%zp <= 0._8 .or. upf%zp > 100 ) then
     write(stdout,'(5x,"readgth: Wrong zp ")')
     return
  end if
  upf%psd=atom_name ( NINT(znucl) )
  call gth_grid_for_rho(upf,znucl)

  read (iunps, *, err=400) pspcod,pspxc,lmax,lloc,mmax,r2well
  IF ( pspcod /= 10 .AND. pspcod /= 12 ) then
     write(stdout,'(5x,"readgth: unknown/invalid pspcod")')
     return
  end if
  IF ( pspcod == 12 ) THEN
     ! pseudo with NLCC
     upf%nlcc=.true.
     upf%generated="New Soft-Accurate NLCC pseudopotentials, generated by Santanu Saha"
     upf%author=TRIM(upf%author)//"/Saha"
  ENDIF
  IF ( lmax-1 > lmaxx ) call upf_error ('readgth', 'strange lmax', lmax-1)
  IF ( lmax == lloc) THEN
     upf%lmax = lmax-1
  ELSE
     upf%lmax = lmax
  ENDIF
  upf%lloc = lloc
  ! write(6, '(2f10.5,2x,i8,t47,a)' )  znucl,upf%zp,pspdat,'znucl, zion, pspdat'
  ! write(6, '(4i5,i10,f10.5,t47,a)' ) pspcod,pspxc,lmax,lloc,mmax,r2well,&
  !  'pspcod,pspxc,lmax,lloc,mmax,r2well'
  gth_p(ns)%lloc=lloc; gth_p(ns)%lmax=lmax

  IF (pspxc == 1) THEN
     upf%dft = 'PZ'
  ELSE IF (pspxc == 7) THEN
     upf%dft = 'PW'
  ELSE IF (pspxc == 11) THEN
     upf%dft = 'PBE'
  ELSE IF (pspxc == 18) THEN
     upf%dft = 'BLYP'
  ELSE IF (pspxc == -101130) THEN ! PBE from libXC
     upf%dft = 'PBE'
  ELSE
     write(stdout,'(5x,"readgth: unknown/invalid pspxc code")')
     return
  ENDIF
  !
  cc(:)=0._8
  !! FIXME: dangerous syntax, are we sure nn has the expected value?
  read (iunps, *, err=400) rloc,nn,(cc(jj),jj=1,nn)
  gth_p(ns)%rloc =rloc
  gth_p(ns)%cc(:)=cc(:)
  ! write(6, '(a,f12.7)' ) ' rloc=',rloc
  ! write(6, '(a,i1,a,4f12.7)' ) ' cc(1:',nn,')=',(cc(jj),jj=1,nn)
  read (iunps, *, err=400) nnonloc
  allocate(hij(0:lmax,3,3),kij(0:lmax,3,3),nproj(lmax+1),gth_p(ns)%rrl(0:lmax))
  hij(:,:,:)=0._8; kij(:,:,:)=0._8
  !
  ! Read and echo the coefficients of non-local projectors
  upf%nbeta=0
  prjloop: do ll=0,lmax
    !! FIXME: dangerous syntax, are we sure nprl has the expected value?
    read (iunps, *, err=400) rrl,nprl,(hij(ll,1,jj),jj=1,nprl)
    upf%nbeta = upf%nbeta + nprl
    gth_p(ns)%rrl(ll)=rrl
    do ii=2,nprl
      read (iunps, *, err=400) (hij(ll,ii,jj),jj=ii,nprl)
    end do
    nproj(ll+1)=nprl
    !   write(6, '(a,i3,a,f12.7,2a,3f12.7,2a,12x,2f12.7,2a,24x,f12.7)' )&
    !&   ' for angular momentum l =',ll,' r(l) =',rrl,ch10,&
    !&   '   h11, h12, h13 =', (hij(ll,1,jj),jj=1,3),ch10,&
    !&   '        h22, h23 =', (hij(ll,2,jj),jj=2,3),ch10,&
    !&   '             h33 =', (hij(ll,3,jj),jj=3,3)
    if (ll==0) cycle
    do ii=1,nprl
      read (iunps, *, err=400) (kij(ll,ii,jj),jj=ii,nprl)
    end do
    !   write(6, '(a,3f12.7,2a,12x,2f12.7,2a,24x,f12.7)' )&
    !&   '   k11, k12, k13 =', (kij(ll,1,jj),jj=1,3),ch10,&
    !&   '        k22, k23 =', (kij(ll,2,jj),jj=2,3),ch10,&
    !&   '             k33 =', (kij(ll,3,jj),jj=3,3)
  end do prjloop
  !
  if (upf%nlcc) then
    read (iunps, *, err=400) rcore, qcore
    ALLOCATE ( upf%rho_atc(upf%mesh) )
    rc2 = rcore**2
    prefact = qcore * (znucl-upf%zp) / (sqrt(tpi)*rcore)**3
    do ii=1,upf%mesh
      upf%rho_atc(ii) = prefact * exp(-0.5_8 * upf%r(ii)**2 / rc2)
    enddo
  end if
  close (unit=iunps)
  !
  allocate(upf%lll(upf%nbeta), upf%els_beta(upf%nbeta), upf%dion(upf%nbeta,upf%nbeta))
  allocate(upf%rcut(upf%nbeta), upf%rcutus(upf%nbeta), upf%kbeta(upf%nbeta))
  upf%rcut(:)  = 0._8
  upf%rcutus(:)= 0._8
  upf%kbeta(:)= 0
  allocate(gth_p(ns)%lll(upf%nbeta), gth_p(ns)%ipr(upf%nbeta))
  iv=0
  lloop: do ll=0,lmax
    nprl=nproj(ll+1)
    iloop: do ii=1,nprl
      iv = iv+1
      gth_p(ns)%lll(iv)=ll
      gth_p(ns)%ipr(iv)=ii
      upf%lll(iv)=ll; WRITE (upf%els_beta(iv), '(I1,A1)' ) ii, l_to_spdf(ll)
      jloop: do jj=ii, nprl
        jv = iv+jj-ii
        upf%dion(iv,jv) = hij(ll,ii,jj)/e2
        if ( jj > ii ) upf%dion(jv,iv) = upf%dion(iv,jv)
      enddo jloop
    enddo iloop
  enddo lloop
  !
  deallocate(hij,kij,nproj)
  ierr = 0 
  return
  !
400 write(stdout,'(5x,"readgth: pseudo file is empty or wrong")' )
  !
end subroutine readgth
!*****************************************************************************************
subroutine gth_grid_for_rho(upf,znucl)
  USE upf_kinds,    ONLY: dp
  USE upf_const,    ONLY: pi, fpi
  USE pseudo_types, ONLY: pseudo_upf
  implicit none
  ! I/O
  TYPE (pseudo_upf) :: upf
  real(8) :: znucl
  ! Local
  integer  :: i, mesh
  real(8) :: xmin, amesh, rmax, rr, rab, length, two_l2, znorml
  !
  xmin = -7.0d0
  amesh=0.0125d0
  rmax =100.0d0
  mesh = 1 + (log(znucl*rmax)-xmin)/amesh
  mesh = (mesh/2)*2+1 ! mesh is odd (Simpson!)
  !
  call atmlength(0._8,length,upf%zp,znucl)
  two_l2=2._8*length**2
  znorml=fpi*upf%zp/(pi*two_l2)**1.5_8
  ALLOCATE (upf%r(mesh), upf%rab(mesh), upf%rho_at(mesh))
  DO i=1, mesh
     rr = exp (xmin+dble(i-1)*amesh)/znucl
     rab= rr*amesh
     upf%r(i)   = rr
     upf%rab(i) = rab
     ! actually 4*pi*r**2*rho(r) !!!
     upf%rho_at(i)=znorml*exp(-rr**2/two_l2)*rr**2
  END DO
  upf%mesh  =mesh
  upf%xmin  =xmin
  upf%rmax  =rmax
  upf%zmesh =znucl
  upf%dx    =amesh
  !
end subroutine gth_grid_for_rho
!*****************************************************************************************
!{\src2tex{textfont=tt}}
!!****f* ABINIT/atmlength
!! NAME
!! atmlength
!!
!! FUNCTION
!! Return atomic decay length for one given type of atom.
!! This length is used to generate an approximate atomic gaussian density
!! in reciprocal space:   n^AT(G)=exp[-(2pi.length.G)^2]
!!
!! COPYRIGHT
!! Copyright (C) 2000-2010 ABINIT group (DCA,XG,MT)
!! This file is distributed under the terms of the
!! GNU General Public License, see ~abinit/COPYING
!! or http://www.gnu.org/copyleft/gpl.txt .
!! For the initials of contributors, see ~abinit/doc/developers/contributors.txt .
!!
!! INPUTS
!! densty=parameter for initialisation of the density of this atom type
!!        if densty>0, returned decay length if densty !
!! zion=charge on current type of atom (real number)
!! znucl=atomic number, for current type of atom
!!
!! OUTPUT
!! length=decay lenth
!!
!! PARENTS
!!      initro
!!
!! CHILDREN
!!
!! SOURCE

subroutine atmlength(densty,length,zion,znucl)

 use upf_kinds, only: dp
 use upf_const, only: tol10=>eps8

 implicit none

!Arguments ------------------------------------
!scalars
 real(8),intent(in) :: densty,zion,znucl
 real(8),intent(out) :: length

!Local variables-------------------------------
!scalars
 integer :: nval
 real(8) :: coreel
!arrays
 real(8) :: data_length(16)

! *************************************************************************

!Either use the input value, or the default value, tabulated now.
 if(abs(densty)>tol10)then
   length=densty
 else

!  Count the number of core electrons.
   coreel=znucl-zion
!  Round the number of valence electrons
   nval=nint(zion)

!  For each set of core electron numbers, there are different decay lengths,
!  they start from nval=1, and proceed by group of 5, until a default is used

   if (nval==0) then
     length=0._8

!    Bare ions : adjusted on 1h and 2he only
   else if(coreel<0.5)then
     data_length(1:4)=(/ .6_8,.4_8,.3_8,.25_8 /)
     length=.2_8
     if(nval<=4)length=data_length(nval)

!    1s2 core : adjusted on 3li, 6c, 7n, and 8o
   else if(coreel<2.5)then
     data_length(1:8)=(/ 1.8_8,1.4_8,1.0_8 ,.7_8,.6_8,&
&     .5_8, .4_8, .35_8 /)
     length=.3_8
     if(nval<=8)length=data_length(nval)

!    Ne core (1s2 2s2 2p6) : adjusted on 11na, 13al, 14si and 17cl
   else if(coreel<10.5)then
     data_length(1:10)=(/ 2.0_8,1.6_8,1.25_8,1.1_8,1.0_8,&
&     .9_8, .8_8, .7_8 , .7_8, .7_8  /)
     length=.6_8
     if(nval<=10)length=data_length(nval)

!    Mg core (1s2 2s2 2p6 3s2) : adjusted on 19k, and on coreel==10
   else if(coreel<12.5)then
     data_length(1:10)=(/ 1.9_8,1.5_8,1.15_8,1.0_8,0.9_8,&
&     .8_8, .7_8, .6_8 , .6_8, .6_8  /)
     length=.5_8
     if(nval<=10)length=data_length(nval)

!    Ar core (Ne + 3s2 3p6) : adjusted on 20ca, 25mn and 30zn
   else if(coreel<18.5)then
     data_length(1:12)=(/ 2.0_8 ,1.8_8 ,1.5_8,1.2_8 ,1.0_8,&
&     .9_8 , .85_8, .8_8, .75_8, .7_8,&
&     .65_8, .65_8 /)
     length=.6_8
     if(nval<=12)length=data_length(nval)

!    Full 3rd shell core (Ar + 3d10) : adjusted on 31ga, 34se and 38sr
   else if(coreel<28.5)then
     data_length(1:14)=(/ 1.5_8 ,1.25_8,1.15_8,1.05_8,1.00_8,&
&     .95_8, .95_8, .9_8 , .9_8 , .85_8,&
&     .85_8, .80_8, .8_8 , .75_8         /)
     length=.7_8
     if(nval<=14)length=data_length(nval)

!    Krypton core (Ar + 3d10 4s2 4p6) : adjusted on 39y, 42mo and 48cd
   else if(coreel<36.5)then
     data_length(1:12)=(/ 2.0_8 ,2.00_8,1.60_8,1.40_8,1.25_8,&
&     1.10_8,1.00_8, .95_8, .90_8, .85_8,&
&     .80_8, .75_8 /)
     length=.7_8
     if(nval<=12)length=data_length(nval)

!    For the remaining elements, consider a function of nval only
   else
     data_length(1:12)=(/ 2.0_8 ,2.00_8,1.55_8,1.25_8,1.15_8,&
&     1.10_8,1.05_8,1.0_8 , .95_8 , .9_8,&
&     .85_8, .85_8 /)
     length=.8_8
     if(nval<=12)length=data_length(nval)

   end if

!  End the choice between default and no-default
 end if

end subroutine atmlength
!!***
end module m_gth
!# 1 "beta_mod.f90"
!# 1 "<built-in>"
!# 1 "<command-line>"
!# 1 "/workspace/q-e/upflib//"
!# 1 "beta_mod.f90"
!
! Copyright (C) 2024 Quantum ESPRESSO Foundation
! This file is distributed under the terms of the
! GNU General Public License. See the file `License'
! in the root directory of the present distribution,
! or http://www.gnu.org/copyleft/gpl.txt .
!
!
MODULE beta_mod
  !
  !! Variables and routines for nonlocal beta functions in numerical form
  !! Contains generation of interpolation tables in reciprocal space,
  !! interpolation routines and other utility routines
  !! Code moved to upflib and restructured by Paolo Giannozzi, 2024
  !
  USE upf_kinds,    ONLY : dp
  USE upf_const,    ONLY : fpi, e2
  !
  IMPLICIT NONE
  !
  PRIVATE
  PUBLIC :: nqx, qmax, tab_beta
  PUBLIC :: init_tab_beta
  PUBLIC :: deallocate_tab_beta
  PUBLIC :: scale_tab_beta
  PUBLIC :: interp_beta
  PUBLIC :: interp_dbeta
  !
  SAVE
  !
  INTEGER :: nqx = 0
  !! size of interpolation table
  REAL(8), PARAMETER:: dq = 0.01_8
  !! grid step for interpolation table
  REAL(8) :: qmax = 0.0_8 
  !! max q covered by the interpolation table
  REAL(8), ALLOCATABLE :: tab_beta(:,:,:)
  !! interpolation table for numerical beta functions in reciprocal space
  !
CONTAINS
!
!----------------------------------------------------------------------
SUBROUTINE init_tab_beta ( qmax_, omega, comm, ierr ) 
  !----------------------------------------------------------------------
  !
  ! Compute interpolation table for beta(G) radial functions
  !
  USE upf_kinds,    ONLY : dp
  USE atom,         ONLY : rgrid
  USE uspp_param,   ONLY : upf, lmaxq, nbetam, nsp
  USE mp,           ONLY : mp_sum
  USE m_gth,        ONLY : mk_ffnl_gth
  !
  IMPLICIT NONE
  !
  REAL(8), INTENT(IN) :: qmax_
  !! Interpolate q up to qmax_ (sqrt(Ry), q^2 is an energy)
  REAL(8), INTENT(IN) :: omega
  !! Unit-cell volume
  INTEGER, INTENT(IN)  :: comm
  !! MPI communicator, to split the workload
  INTEGER, INTENT(OUT) :: ierr
  !! error code: ierr = 0 if interpolation table (IT) was allocated
  !!             ierr =-1 if IT had insufficient size and was re-allocated
  !!             ierr =-2 if IT was already present and nothing is done
  !
  INTEGER :: ndm, startq, lastq, nt, l, nb, iq, ir
  REAL(8) :: qi
  ! q-point grid for interpolation
  REAL(8) :: pref
  ! the prefactor of the Q functions
  real(8) ::  vqint, d1
  !
  REAL(8), allocatable :: aux (:)
  ! work space
  REAL(8), allocatable :: besr(:)
  ! work space
  !
  IF ( .NOT. ALLOCATED(tab_beta) ) THEN
     !! table not yet allocated
     qmax = qmax_
     ierr = 0
  ELSE IF ( qmax_ > qmax ) THEN
     !! table ìs allocated but dimension insufficient: re-allocate
     !! (with some margin so that this does not happen too often)
     DEALLOCATE ( tab_beta )
     qmax = qmax_ + MAX(dq*100,qmax_-qmax)
     ierr =-1
  ELSE
     !! table already computed: exit
     ierr =-2
     RETURN
  END IF
  nqx = INT( qmax/dq + 4)
  allocate(tab_beta(nqx,nbetam,nsp))
  ndm = MAXVAL ( upf(:)%kkbeta )
  allocate( aux (ndm) )
  allocate (besr( ndm))
  pref = fpi / sqrt (omega)
  call divide (comm, nqx, startq, lastq)
  tab_beta (:,:,:) = 0.d0
  do nt = 1, nsp
     do nb = 1, upf(nt)%nbeta
        l = upf(nt)%lll (nb)
        do iq = startq, lastq
           qi = (iq - 1) * dq
           if ( upf(nt)%is_gth ) then
              CALL mk_ffnl_gth( nt, nb, 1, omega, [ qi ] , tab_beta(iq,nb,nt) )
           else
              call sph_bes (upf(nt)%kkbeta, rgrid(nt)%r, qi, l, besr)
              do ir = 1, upf(nt)%kkbeta
                 aux (ir) = upf(nt)%beta (ir, nb) * besr (ir) * rgrid(nt)%r(ir)
              enddo
              call simpson (upf(nt)%kkbeta, aux, rgrid(nt)%rab, vqint)
              tab_beta (iq, nb, nt) = vqint * pref
           end if
        enddo
     enddo
  enddo
  deallocate (besr)
  deallocate (aux)
  !
  call mp_sum(  tab_beta, comm )
  !
END SUBROUTINE init_tab_beta
!
!----------------------------------------------------------------------
SUBROUTINE interp_beta( nt, npw_, qg, vq )
  !----------------------------------------------------------------------
  !
  USE upf_kinds,  ONLY : dp
  USE uspp_param, ONLY : upf, nbetam
  !
  implicit none
  integer, intent(in) :: nt, npw_
  real(8), intent(in ) :: qg(npw_)
  real(8), intent(out) :: vq(npw_,nbetam)
  !
  integer :: i0, i1, i2, i3, nbnt, nb, ig
  real(8):: qgr, px, ux, vx, wx
  !
  nbnt = upf(nt)%nbeta
  do nb = 1, nbnt
     DO ig = 1, npw_
        qgr = qg(ig)
        px = qgr / dq - DBLE(INT(qgr/dq))
        ux = 1.0_8 - px
        vx = 2.0_8 - px
        wx = 3.0_8 - px
        i0 = INT(qgr/dq) + 1
        i1 = i0 + 1
        i2 = i0 + 2
        i3 = i0 + 3
        if ( i3 <= nqx ) then
           vq(ig,nb) = &
             tab_beta(i0,nb,nt) * ux * vx * wx / 6.0_8 + &
             tab_beta(i1,nb,nt) * px * vx * wx / 2.0_8 - &
             tab_beta(i2,nb,nt) * px * ux * wx / 2.0_8 + &
             tab_beta(i3,nb,nt) * px * ux * vx / 6.0_8
        else
           !! This case should never happen if tab_beta is properly allocated
           !! (setting q_max to be large enough) - for compatibility with GWW
           vq(ig,nb) = 0.0_8
        end if
     END DO
  END DO
  !----------------------------------------------------------------------
END SUBROUTINE interp_beta
!----------------------------------------------------------------------
!
!----------------------------------------------------------------------
SUBROUTINE interp_dbeta( nt, npw, qg, vq )
  !----------------------------------------------------------------------
  !
  USE upf_kinds,  ONLY : dp
  USE uspp_param, ONLY : upf, nbetam
  !
  implicit none
  integer, intent(in) :: nt, npw
  real(8), intent(in ) :: qg(npw)
  real(8), intent(out) :: vq(npw,nbetam)
  !
  integer :: i0, i1, i2, i3, nbnt, nb, ig
  real(8):: qgr, px, ux, vx, wx
  !
  nbnt = upf(nt)%nbeta
  DO nb = 1, nbnt
     DO ig = 1, npw
        qgr = qg(ig)
        px = qgr / dq - INT(qgr/dq)
        ux = 1.0_8 - px
        vx = 2.0_8 - px
        wx = 3.0_8 - px
        i0 = qgr / dq + 1
        i1 = i0 + 1
        i2 = i0 + 2
        i3 = i0 + 3
        IF ( i3 <= nqx ) THEN
            vq(ig,nb) = ( tab_beta(i0,nb,nt) * (-vx*wx-ux*wx-ux*vx)/6.0_8 + &
                          tab_beta(i1,nb,nt) * (+vx*wx-px*wx-px*vx)/2.0_8 - &
                          tab_beta(i2,nb,nt) * (+ux*wx-px*wx-px*ux)/2.0_8 + &
                          tab_beta(i3,nb,nt) * (+ux*vx-px*vx-px*ux)/6.0_8 )/dq
        ELSE
            vq(ig,nb) = 0.0_8 
        END IF
     ENDDO
  END DO
  !----------------------------------------------------------------------
END SUBROUTINE interp_dbeta
!
  subroutine deallocate_tab_beta ()
    implicit none
    !
    if( allocated( tab_beta ) )  deallocate( tab_beta )
    !
  end subroutine deallocate_tab_beta
  !
  subroutine scale_tab_beta( vol_ratio_m1 )
    ! vol_ratio_m1 = omega_old / omega
    implicit none
    real(8), intent(in) :: vol_ratio_m1
    !
    tab_beta(:,:,:) = tab_beta(:,:,:) * SQRT(vol_ratio_m1)
  end subroutine scale_tab_beta
   !
END MODULE beta_mod

